175	{
176	    public async Task<ExternalLinkResult> LinkAsync(
177	        UserId userId,
178	        ExternalIdentityDescriptor identity,
179	        CancellationToken cancellationToken)
180	    {
181	        if (string.IsNullOrWhiteSpace(identity.Provider) || string.IsNullOrWhiteSpace(identity.Subject))
182	            return ExternalLinkResult.Failure("invalid_external_identity");
183	
184	        var user = await users.FindAsync(userId, cancellationToken);
185	        if (user is null || !user.IsEnabled)
186	            return ExternalLinkResult.Failure("user_not_found");
187	
188	        var existing = await links.FindAsync(identity.Provider, identity.Subject, cancellationToken);
189	        if (existing is not null)
190	            return existing.UserId == userId
191	                ? ExternalLinkResult.Failure("external_identity_already_linked")
192	                : ExternalLinkResult.Failure("external_identity_linked_to_another_user");
193	
194	        var userLinks = await links.FindForUserAsync(userId, cancellationToken);
195	        if (userLinks.Any(x => string.Equals(x.Provider, identity.Provider, StringComparison.OrdinalIgnoreCase) &&
196	                               string.Equals(x.Subject, identity.Subject, StringComparison.Ordinal)))
197	            return ExternalLinkResult.Failure("external_identity_already_linked");
198	
199	        await links.AddAsync(new ExternalIdentityLink(
200	            Guid.NewGuid(), userId, identity.Provider, identity.Subject, clock.UtcNow), cancellationToken);
201	        return ExternalLinkResult.Success();
202	    }
