205	public sealed class LocalAuthenticationService(
206	    IUserRepository users,
207	    IPasswordCredentialStore credentials,
208	    IPermissionRepository permissions,
209	    ISessionStore sessions,
210	    IRefreshTokenStore refreshTokens,
211	    IPasswordVerifier passwordVerifier,
212	    IAccessTokenIssuer tokenIssuer,
213	    ISystemClock clock)
214	{
215	    public async Task<AuthenticationResult> LoginAsync(string username, string password,
216	        CancellationToken cancellationToken)
217	    {
218	        var user = await users.FindByUsernameAsync(username.Trim(), cancellationToken);
219	        if (user is null || !user.IsEnabled) return AuthenticationResult.Failure("invalid_credentials");
220	        if (user.IsLocked(clock.UtcNow)) return AuthenticationResult.Failure("account_locked");
221	        var credential = await credentials.FindAsync(user.Id, cancellationToken);
222	        if (credential is null || !passwordVerifier.Verify(credential.PasswordHash, password))
223	        {
224	            user.RecordFailedLogin(clock.UtcNow, 5, TimeSpan.FromMinutes(15));
225	            await users.SaveAsync(user, cancellationToken);
226	            return AuthenticationResult.Failure("invalid_credentials");
227	        }
228	
229	        user.RecordSuccessfulLogin(clock.UtcNow);
230	        await users.SaveAsync(user, cancellationToken);
231	        return await IssueTokensAsync(user, cancellationToken);
232	    }
233	
234	    public async Task<AuthenticationResult> IssueTokensAsync(
235	        User user,
236	        CancellationToken cancellationToken)
237	    {
238	        if (!user.IsEnabled || user.IsLocked(clock.UtcNow))
239	            return AuthenticationResult.Failure("session_invalid");
240	        var session = new UserSession(
241	            Guid.NewGuid(),
242	            user.Id,
243	            clock.UtcNow,
244	            clock.UtcNow.AddHours(8),
245	            user.SecurityStamp);
246	        await sessions.AddAsync(session, cancellationToken);
247	        var effectivePermissions = await permissions.GetEffectivePermissionsAsync(user.Id, cancellationToken);
248	        var access = await tokenIssuer.IssueAsync(
249	            user,
250	            effectivePermissions,
251	            session.Id,
252	            cancellationToken);
253	        var rawRefresh = TokenGenerator.Generate();
254	        var refresh = new RefreshTokenRecord(
255	            Guid.NewGuid(),
256	            user.Id,
257	            session.Id,
258	            TokenGenerator.Hash(rawRefresh),
259	            Guid.NewGuid().ToString("N"),
260	            clock.UtcNow.AddDays(30),
261	            clock.UtcNow);
262	        await refreshTokens.AddAsync(refresh, cancellationToken);
263	        return new AuthenticationResult(true, access, rawRefresh, session.Id, null);
264	    }
265	
266	    public async Task<SessionAuthenticationResult> LoginForSessionAsync(
267	        string username,
268	        string password,
269	        CancellationToken cancellationToken)
270	    {
271	        var user = await users.FindByUsernameAsync(username.Trim(), cancellationToken);
272	        if (user is null || !user.IsEnabled)
273	            return SessionAuthenticationResult.Failure("invalid_credentials");
274	        if (user.IsLocked(clock.UtcNow))
275	            return SessionAuthenticationResult.Failure("account_locked");
276	
277	        var credential = await credentials.FindAsync(user.Id, cancellationToken);
278	        if (credential is null || !passwordVerifier.Verify(credential.PasswordHash, password))
279	        {
280	            user.RecordFailedLogin(clock.UtcNow, 5, TimeSpan.FromMinutes(15));
281	            await users.SaveAsync(user, cancellationToken);
282	            return SessionAuthenticationResult.Failure("invalid_credentials");
283	        }
284	
285	        user.RecordSuccessfulLogin(clock.UtcNow);
286	        await users.SaveAsync(user, cancellationToken);
287	        var session = new UserSession(
288	            Guid.NewGuid(),
289	            user.Id,
290	            clock.UtcNow,
291	            clock.UtcNow.AddHours(8),
292	            user.SecurityStamp);
293	        await sessions.AddAsync(session, cancellationToken);
294	        return new SessionAuthenticationResult(
295	            true,
296	            session.Id,
297	            user.Id.Value,
298	            user.Username,
299	            user.DisplayName,
300	            null);
301	    }
302	
303	    public async Task<AuthenticationResult> RefreshAsync(string rawRefreshToken, CancellationToken cancellationToken)
304	    {
305	        if (string.IsNullOrWhiteSpace(rawRefreshToken)) return AuthenticationResult.Failure("invalid_refresh_token");
306	        var current = await refreshTokens.FindAsync(TokenGenerator.Hash(rawRefreshToken), cancellationToken);
307	        if (current is null) return AuthenticationResult.Failure("invalid_refresh_token");
308	        if (!current.IsActive(clock.UtcNow))
309	        {
310	            await refreshTokens.RevokeFamilyAsync(current.FamilyId, clock.UtcNow, cancellationToken);
311	            return AuthenticationResult.Failure("refresh_token_reuse_detected");
312	        }
313	
314	        var session = await sessions.FindAsync(current.SessionId, cancellationToken);
315	        var user = await users.FindAsync(current.UserId, cancellationToken);
316	        if (session is null || user is null || !session.IsActive(clock.UtcNow) || !user.IsEnabled ||
317	            user.IsLocked(clock.UtcNow))
318	            return AuthenticationResult.Failure("session_invalid");
319	        var rawReplacement = TokenGenerator.Generate();
320	        var replacement = new RefreshTokenRecord(Guid.NewGuid(), user.Id, session.Id,
321	            TokenGenerator.Hash(rawReplacement), current.FamilyId, clock.UtcNow.AddDays(30), clock.UtcNow);
322	        current.Replace(replacement.TokenHash, clock.UtcNow);
323	        await refreshTokens.RotateAsync(current, replacement, cancellationToken);
324	        var effectivePermissions = await permissions.GetEffectivePermissionsAsync(user.Id, cancellationToken);
325	        var access = await tokenIssuer.IssueAsync(user, effectivePermissions, session.Id, cancellationToken);
326	        return new AuthenticationResult(true, access, rawReplacement, session.Id, null);
327	    }
328	
329	    public async Task<bool> LogoutAsync(
330	        UserId userId,
331	        Guid sessionId,
332	        CancellationToken cancellationToken)
333	    {
334	        var session = await sessions.FindAsync(sessionId, cancellationToken);
335	        if (session is null || session.UserId != userId)
336	            return false;
337	
338	        await sessions.RevokeAsync(session, clock.UtcNow, cancellationToken);
339	        return true;
340	    }
341	
342	    public async Task<int> LogoutAllAsync(UserId userId, CancellationToken cancellationToken)
343	    {
344	        var now = clock.UtcNow;
345	        var activeSessions = (await sessions.FindForUserAsync(userId, cancellationToken))
346	            .Where(x => x.IsActive(now))
347	            .ToArray();
348	        foreach (var session in activeSessions)
349	            await sessions.RevokeAsync(session, now, cancellationToken);
350	        return activeSessions.Length;
351	    }
352	
353	    public static class TokenGenerator
354	    {
355	        public static string Generate() =>
356	            Convert.ToBase64String(System.Security.Cryptography.RandomNumberGenerator.GetBytes(48));
357	
358	        public static string Hash(string value) => Convert
359	            .ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(value)))
360	            .ToLowerInvariant();
361	    }
362	}
363	
364	public sealed class PermissionManifestSynchronizer(
365	    IPermissionRepository repository,
366	    IPermissionManifestVersionStore versions,
367	    IUnitOfWork? unitOfWork = null)
368	{
369	    public Task<bool> SynchronizeAsync(PermissionManifest manifest, CancellationToken cancellationToken)
370	        => unitOfWork is null
371	            ? SynchronizeCoreAsync(manifest, cancellationToken)
372	            : unitOfWork.ExecuteInTransactionAsync(
373	                operationCancellationToken => SynchronizeCoreAsync(manifest, operationCancellationToken),
374	                cancellationToken);
375	
376	    private async Task<bool> SynchronizeCoreAsync(PermissionManifest manifest, CancellationToken cancellationToken)
377	    {
378	        if (!await versions.TryAcceptAsync(manifest, cancellationToken))
379	            return false;
380	        await repository.UpsertManifestAsync(manifest, cancellationToken);
381	        return true;
382	    }
383	}
384	
385	public sealed class PermissionAuthorizationService(IPermissionRepository permissions)
386	{
387	    public async Task<bool> HasPermissionAsync(UserId userId, string permission, CancellationToken cancellationToken)
388	        => (await permissions.GetEffectivePermissionsAsync(userId, cancellationToken)).Contains(permission,
389	            StringComparer.Ordinal);
390	}

