386	static void ValidateExternalProviderOptions(
387	    string authority,
388	    string clientId,
389	    bool requireHttpsMetadata,
390	    TimeSpan timeout,
391	    string providerName)
392	{
393	    if (!Uri.TryCreate(authority, UriKind.Absolute, out var authorityUri) ||
394	        (requireHttpsMetadata && authorityUri.Scheme != Uri.UriSchemeHttps))
395	        throw new InvalidOperationException(
396	            $"{providerName} authority must be an absolute HTTPS URI when HTTPS metadata is required.");
397	    if (string.IsNullOrWhiteSpace(clientId))
