52	    {
53	        FailedLoginCount++;
54	        if (FailedLoginCount >= threshold) LockedUntil = now.Add(lockout);
55	        UpdatedAt = now;
56	    }
57	
58	    public void RecordSuccessfulLogin(DateTimeOffset now)
59	    {
60	        FailedLoginCount = 0;
61	        LockedUntil = null;
62	        UpdatedAt = now;
63	    }
