message UserResponse { string id = 1; string username = 2; string display_name = 3; bool enabled = 4; map<string, string> attributes = 5; }
message UserListResponse { repeated UserResponse items = 1; int32 page = 2; int32 page_size = 3; int32 total = 4; }
message RoleResponse { string id = 1; string name = 2; string description = 3; string client_id = 4; bool composite = 5; }
message RoleListResponse { repeated RoleResponse items = 1; int32 page = 2; int32 page_size = 3; int32 total = 4; }
message PermissionResponse { string name = 1; string description = 2; string service_id = 3; string service_version = 4; bool deprecated = 5; string keycloak_role_id = 6; }
