        var now = DateTimeOffset.UtcNow;
        var user = new User(UserId.New(), "alice", "Alice", now);
        var p = PermissionId.New();
        user.GrantPermission(p, now);
        user.GrantPermission(p, now);
        Assert.Single(user.DirectPermissions);
    }
