12	public sealed class Pbkdf2PasswordVerifier : IPasswordVerifier
13	{
14	    private const int SaltSize = 16;
15	    private const int KeySize = 32;
16	    private const int Iterations = 210_000;
17	
18	    public string Hash(string password)
19	    {
20	        var salt = RandomNumberGenerator.GetBytes(SaltSize);
21	        var key = Rfc2898DeriveBytes.Pbkdf2(password, salt, Iterations, HashAlgorithmName.SHA512, KeySize);
22	        return $"pbkdf2-sha512:{Iterations}:{Convert.ToBase64String(salt)}:{Convert.ToBase64String(key)}";
23	    }
24	
25	    public bool Verify(string encodedHash, string password)
26	    {
27	        try
28	        {
29	            var parts = encodedHash.Split(':');
30	            if (parts.Length != 4 || parts[0] != "pbkdf2-sha512") return false;
31	            var iterations = int.Parse(parts[1], System.Globalization.CultureInfo.InvariantCulture);
32	            var salt = Convert.FromBase64String(parts[2]);
33	            var expected = Convert.FromBase64String(parts[3]);
34	            var actual =
35	                Rfc2898DeriveBytes.Pbkdf2(password, salt, iterations, HashAlgorithmName.SHA512, expected.Length);
36	            return CryptographicOperations.FixedTimeEquals(actual, expected);
37	        }
38	        catch (FormatException)
39	        {
40	            return false;
41	        }
42	        catch (ArgumentException)
