        var canonical = JsonSerializer.Serialize(new { serviceId, serviceVersion = options.ServiceVersion, manifestVersion = options.ManifestVersion, permissions });
        var hash = "sha256:" + Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(canonical))).ToLowerInvariant();
        return new(serviceId, options.ServiceVersion, options.ManifestVersion, permissions, hash);
    }
}
