using System.Reflection;
using NetArchTest.Rules;

namespace Identity.ArchitectureTests;

public sealed class ArchitectureTests
{
    [Fact]
    public void Domain_assembly_has_no_transport_or_adapter_references()
    {
        var domain = Types.InAssembly(typeof(Identity.Domain.PermissionManifest).Assembly);
        Assert.True(domain.That().HaveDependencyOn("Microsoft.EntityFrameworkCore").GetResult().IsSuccessful is false);
        Assert.True(domain.That().HaveDependencyOn("Microsoft.AspNetCore").GetResult().IsSuccessful is false);
        Assert.True(domain.That().HaveDependencyOn("Grpc").GetResult().IsSuccessful is false);
    }

    [Fact]
    public void Application_has_no_keycloak_or_ef_or_redis_references()
    {
        var app = Types.InAssembly(typeof(Identity.Application.IUserDirectory).Assembly);
        Assert.True(app.That().HaveDependencyOn("EntityFrameworkCore").GetResult().IsSuccessful is false);
        Assert.True(app.That().HaveDependencyOn("StackExchange.Redis").GetResult().IsSuccessful is false);
        Assert.True(app.That().HaveDependencyOn("Microsoft.AspNetCore.Http").GetResult().IsSuccessful is false);
    }

    [Fact]
    public void Authentication_has_no_authorization_dependency()
    {
        var result = Types
            .InAssembly(typeof(Company.Identity.Authentication.IdentityAuthenticationOptions).Assembly)
            .That()
            .HaveDependencyOn("Company.Identity.Authorization")
            .GetResult();
        Assert.False(result.IsSuccessful);
    }

    [Fact]
    public void Domain_types_surface_is_facade_owned_only()
    {
        var names = typeof(Identity.Domain.PermissionDefinition).Assembly
            .GetTypes().Where(x => x.Namespace == "Identity.Domain").Select(x => x.Name).ToArray();
        Assert.DoesNotContain("User", names);
        Assert.DoesNotContain("RefreshTokenRecord", names);
        Assert.DoesNotContain("UserSession", names);
    }
}

