6	public sealed class HttpCurrentUserContext(IHttpContextAccessor accessor, TimeProvider timeProvider) : ICurrentUserContext
7	{
8	    private ClaimsPrincipal Principal => accessor.HttpContext?.User ?? new ClaimsPrincipal(new ClaimsIdentity());
9	    public string? UserId => Principal.FindFirstValue("sub");
10	    public string? Username => Principal.FindFirstValue("preferred_username") ?? Principal.Identity?.Name;
