                att = obj.get("attachment", {}) or {}
                if att.get("type","").startswith("hook_"):
                    key = (att.get("hookName","?"), att.get("hookEvent","?"), att.get("type"))
                    hook_counts[key]+=1
                    if "durationMs" in att: hook_durs[key].append(att["durationMs"])
            if obj.get("toolDenialKind"):
                denials.append((obj.get("toolDenialKind"), path))
                # find matching tool_use
                # we just count denials per kind
            # tool_use
            if t=="assistant":
                for c in (obj.get("message",{}).get("content") or []):
                    if c.get("type")=="tool_use":
                        name=c.get("name","")
                        if name=="Skill":
                            skill_hits[c.get("input",{}).get("skill","?")]+=1
                        elif name.startswith("mcp__"):
                            mcp_hits[name]+=1
            # slash
            if t=="user":
                content = obj.get("message",{}).get("content") if isinstance(obj.get("message"), dict) else obj.get("message")
                txt = ""
                if isinstance(content, list):
                    for blk in content:
                        if isinstance(blk, dict) and "text" in blk: txt+=blk["text"]
                        elif isinstance(blk, str): txt+=blk
                elif isinstance(content, str): txt=content
                else: txt=str(obj.get("message",""))
                # also check raw content string
                raw = line
                for m in re.finditer(r"<command-name>([^<]+)</command-name>", raw):
                    slash_hits[m.group(1)]+=1
    except Exception as e:
        print(f"err {path}: {e}")
print("hooks:", dict(hook_counts) if hook_counts else "none in window")
for k,v in hook_durs.items():
    print(f"  {k}: {len(v)} runs, median {sorted(v)[len(v)//2]}ms, max {max(v)}ms")
print("denials:", collections.Counter(k for k,_ in denials) if denials else "none")
print("skill tool_use hits:", dict(skill_hits) if skill_hits else "none")
print("slash hits:", dict(slash_hits) if slash_hits else "none")
print("mcp tool hits:", dict(mcp_hits) if mcp_hits else "none")
