files = sorted(glob.glob(os.path.expanduser("~/.claude/projects/**/*.jsonl"), recursive=True), key=lambda p: os.path.getmtime(p), reverse=True)[:50]
# Detailed denial breakdown by tool/command
denied_tools = collections.Counter()
denied_by_kind = collections.defaultdict(collections.Counter)
# Need to map tool_use_id -> tool_use for denials
tool_uses = {}  # id -> (name, input)
for path in files:
    for line in open(path, errors="ignore"):
        try:
            obj=json.loads(line)
        except: continue
        if obj.get("type")=="assistant":
            for c in (obj.get("message",{}).get("content") or []):
                if c.get("type")=="tool_use":
                    tid=c.get("id")
                    if tid:
                        tool_uses[tid]=(c.get("name"), c.get("input",{}))
# Now collect denials
for path in files:
    for line in open(path, errors="ignore"):
        try:
            obj=json.loads(line)
        except: continue
        kind=obj.get("toolDenialKind")
        if not kind or kind in ("interrupted","cancelled"):
            continue
        # find tool result id
