        msg=obj.get("message",{})
        content=msg.get("content") if isinstance(msg, dict) else None
        tids=[]
        if isinstance(content, list):
            for blk in content:
                if isinstance(blk, dict) and blk.get("type")=="tool_result":
                    tid=blk.get("tool_use_id")
                    if tid: tids.append(tid)
        for tid in tids:
            name, inp = tool_uses.get(tid, ("?(unknown)", {}))
            # For Bash, key on command prefix
            if name=="Bash":
                cmd=inp.get("command","") if isinstance(inp, dict) else ""
                # first line, first subcommand-ish
                first = cmd.strip().split("\n")[0][:120]
                key = f"Bash:{first[:80]}"
            else:
                key = name
            denied_tools[key]+=1
