                        !string.Equals(type, "Bearer", StringComparison.OrdinalIgnoreCase) &&
                        !string.Equals(type, "at+jwt", StringComparison.OrdinalIgnoreCase)) context.Fail("Unexpected token type.");
                    return Task.CompletedTask;
                }
            };
        });
        return services;
    }
