    string? Username { get; }
    IReadOnlyCollection<string> Roles { get; }
    IReadOnlyCollection<string> Permissions { get; }
    IReadOnlyDictionary<string, string?> Claims { get; }
    string? SessionId { get; }
    DateTimeOffset RequestDateTime { get; }
}

