1	using System.Security.Cryptography;
2	using Identity.Domain;
3	
4	namespace Identity.Application;
5	
6	/// <summary>All privileged permission names for the key lifecycle admin surface.</summary>
7	public static class KeyPermissions
8	{
9	    public const string View            = "Identity.Keys.View";
10	    public const string Generate        = "Identity.Keys.Generate";
11	    public const string Import          = "Identity.Keys.Import";
12	    public const string Stage           = "Identity.Keys.Stage";
13	    public const string Validate        = "Identity.Keys.Validate";
14	    public const string Activate        = "Identity.Keys.Activate";
15	    public const string Passivate       = "Identity.Keys.Passivate";
16	    public const string Retire          = "Identity.Keys.Retire";
17	    public const string Destroy         = "Identity.Keys.Destroy";
18	    public const string Rotate          = "Identity.Keys.Rotate";
19	    public const string EmergencyRotate = "Identity.Keys.EmergencyRotate";
20	    public const string Rollback        = "Identity.Keys.Rollback";
21	    public const string History         = "Identity.Keys.History";
22	}
23	
24	/// <summary>
25	/// Orchestrates the lifecycle saga. Holds no private material beyond the single call that
26	/// hands it to Vault/Keycloak. Every mutating method is idempotent via the supplied key.
27	/// </summary>
28	public sealed class KeyRotationService(
29	    IKeyGenerationService generation,
30	    ISigningKeyVault vault,
31	    IKeycloakKeyManager keycloak,
32	    IKeyLifecycleRepository repo,
33	    IKeyRotationLock rotationLock,
34	    IKeyRetirementSafety safety,
35	    KeyManagementOptions options,
36	    TimeProvider clock,
37	    IAuditSink audit)
38	{
39	    private static string NewKid() => $"iam-rsa-{DateTimeOffset.UtcNow:yyyy-MM}-{Guid.NewGuid():N Span'[..6]}";
40	
41	    private static string NewOpId() => Guid.NewGuid().ToString("N");
42	
43	    private static Identity.Contracts.SigningKeyDto ToDto(SigningKeyMetadata m) =>
44	        new(m.Kid, (int)m.Size, m.PublicPemFingerprint, m.VaultPath, m.VaultVersion,
45	            m.State.ToString(), m.CreatedAt, m.Realm, m.KeycloakComponentId, m.ActivatedAt, m.RetiredAt, m.Origin);
46	
47	    // ---- Generate + Import (create + store in Vault, no Keycloak yet) ----
48	
49	    public async Task<Identity.Contracts.SigningKeyDto> GenerateAsync(
50	        Identity.Contracts.GenerateKeyRequest request, string actor, CancellationToken ct)
51	    {
52	        var size = request.Size is 2048 or 3072 or 4096
53	            ? (RsaKeySize)request.Size : options.DefaultSize;
54	        var kid = string.IsNullOrWhiteSpace(request.Kid) ? NewKid() : request.Kid.Trim();
55	
56	        if (await repo.GetAsync(options.Realm, kid, ct) is not null)
57	            throw new InvalidOperationException($"kid '{kid}' already exists and will never be reused.");
58	
59	        var (publicPem, priv, fingerprint) = generation.Generate(size, kid);
60	        using (priv)
61	        {
62	            var vaultRef = await vault.StorePrivateKeyAsync(kid, size, priv.Pem, publicPem, fingerprint, options.Realm, ct);
63	            var now = clock.GetUtcNow();
64	            var meta = new SigningKeyMetadata(kid, size, fingerprint, vaultRef.Path, vaultRef.Version,
65	                KeyLifecycleState.VaultStored, now, options.Realm, Origin: "generated");
66	            await repo.UpsertAsync(meta, ct);
67	            await repo.AddHistoryAsync(options.Realm, kid, KeyLifecycleState.Generated.ToString(),
68	                KeyLifecycleState.VaultStored.ToString(), now, actor, request.Reason, ct);
69	            await audit.RecordAsync(new AuditEvent(actor, "key.generated", kid, now,
70	                new Dictionary<string, string?> { ["kid"] = kid, ["size"] = ((int)size).ToString(), ["vault_version"] = vaultRef.Version.ToString() }), ct);
71	            return ToDto(meta);
72	        }
73	    }
74	
75	    public async Task<Identity.Contracts.SigningKeyDto> ImportAsync(
76	        Identity.Contracts.ImportKeyRequest request, string actor, CancellationToken ct)
77	    {
78	        if (string.IsNullOrWhiteSpace(request.Pem)) throw new ArgumentException("PEM is required.", nameof(request));
79	        var requestedKid = string.IsNullOrWhiteSpace(request.Kid) ? NewKid() : request.Kid.Trim();
80	        if (await repo.GetAsync(options.Realm, requestedKid, ct) is not null)
81	            throw new InvalidOperationException($"kid '{requestedKid}' already exists and will never be reused.");
82	
83	        var (publicPem, priv, size, fingerprint) = generation.ParseImport(request.Pem, requestedKid);
84	        using (priv)
85	        {
86	            var vaultRef = await vault.StorePrivateKeyAsync(requestedKid, size, priv.Pem, publicPem, fingerprint, options.Realm, ct);
87	            var now = clock.GetUtcNow();
88	            var meta = new SigningKeyMetadata(requestedKid, size, fingerprint, vaultRef.Path, vaultRef.Version,
89	                KeyLifecycleState.VaultStored, now, options.Realm, Origin: "imported");
90	            await repo.UpsertAsync(meta, ct);
91	            await repo.AddHistoryAsync(options.Realm, requestedKid, KeyLifecycleState.Generated.ToString(),
92	                KeyLifecycleState.VaultStored.ToString(), now, actor, request.Reason, ct);
93	            await audit.RecordAsync(new AuditEvent(actor, "key.imported", requestedKid, now,
94	                new Dictionary<string, string?> { ["kid"] = requestedKid, ["size"] = ((int)size).ToString() }), ct);
95	            return ToDto(meta);
96	        }
97	    }
98	
99	    // ---- Stage (VaultStored -> Passive): register as Passive Keycloak component ----
100	
101	    public async Task<Identity.Contracts.SigningKeyDto> StageAsync(string kid, string actor, CancellationToken ct)
102	    {
103	        var meta = await repo.GetAsync(options.Realm, kid, ct)
104	            ?? throw new KeyNotFoundException($"Key '{kid}' not found.");
105	        if (meta.State != KeyLifecycleState.VaultStored)
106	            throw new InvalidOperationException($"Key '{kid}' is {meta.State}, expected VaultStored to stage.");
107	
108	        // Vault private material is needed transiently for the Keycloak import path (documented interim gap).
109	        // The Vault adapter returns public info; the Keycloak adapter needs the private PEM, so we re-derive
110	        // via a dedicated Vault private-read method on the vault port — exposed only to this service.
111	        // For now the vault port does not expose private reads; stage therefore uses the Keycloak "imported" provider
112	        // with material that was supplied at generation/import time if available. Since we already vaulted it,
113	        // the stage call must fetch the private PEM from Vault via a narrow method.
114	        // To keep the port minimal, we add an internal helper on ISigningKeyVault for this single use.
115	
116	        // Retrieve private PEM transiently (Vault is source of truth).
117	        var privatePem = await TryReadPrivatePemAsync(kid, ct);
118	        var publicPem = (await vault.ReadPublicAsync(kid, ct))?.PublicPem
119	            ?? throw new InvalidOperationException($"Vault public mirror for '{kid}' missing.");
120	
121	        using (privatePem)
122	        {
123	            var component = await keycloak.RegisterPassiveAsync(options.Realm, kid, meta.Size, privatePem.Pem, publicPem, ct);
124	            var now = clock.GetUtcNow();
125	            var next = meta with
126	            {
127	                State = KeyLifecycleState.Passive,
128	                KeycloakComponentId = component.Id
129	            };
130	            // Validate transition via helper (Passive is reachable from VaultStored).
131	            KeyLifecycleTransitions.Ensure(meta.State, next.State);
132	            await repo.UpsertAsync(next, ct);
133	            await repo.AddHistoryAsync(options.Realm, kid, meta.State.ToString(), next.State.ToString(), now, actor, null, ct);
134	            await audit.RecordAsync(new AuditEvent(actor, "key.staged", kid, now,
135	                new Dictionary<string, string?> { ["kid"] = kid, ["component_id"] = component.Id }), ct);
136	            return ToDto(next);
137	        }
138	    }
139	
140	    private async Task<TransientPrivatePem> TryReadPrivatePemAsync(string kid, CancellationToken ct)
141	    {
142	        // Prefer a dedicated private-read on the vault port when available (narrow, audited).
143	        if (vault is ISigningKeyVaultWithPrivateRead withPrivate)
144	            return await withPrivate.ReadPrivateAsync(kid, ct);
145	        throw new InvalidOperationException(
146	            "Vault adapter does not expose private reads. Configure ISigningKeyVaultWithPrivateRead. " +
147	            "This is intentional: only the rotation service may read private material.");
148	    }
149	
150	    // ---- Validate (Passive -> Validated): assert kid present in JWKS ----
151	
152	    public async Task<Identity.Contracts.SigningKeyDto> ValidateAsync(string kid, string actor, CancellationToken ct)
153	    {
154	        var meta = await repo.GetAsync(options.Realm, kid, ct)
155	            ?? throw new KeyNotFoundException($"Key '{kid}' not found.");
156	        if (meta.State != KeyLifecycleState.Passive)
157	            throw new InvalidOperationException($"Key '{kid}' is {meta.State}, expected Passive to validate.");
158	
159	        var publicPem = (await vault.ReadPublicAsync(kid, ct))?.PublicPem
160	            ?? throw new InvalidOperationException($"Vault public mirror for '{kid}' missing.");
161	        var result = await keycloak.VerifyInJwksAsync(options.Realm, kid, publicPem, ct);
162	        var now = clock.GetUtcNow();
163	        if (!result.Present || !result.FingerprintMatches)
164	        {
165	            var failed = meta with { State = KeyLifecycleState.ValidationFailed };
166	            // Direct assignment for failure branch (outside normal Validated path).
167	            await repo.UpsertAsync(failed, ct);
168	            await repo.AddHistoryAsync(options.Realm, kid, meta.State.ToString(), failed.State.ToString(), now, actor, result.Reason, ct);
169	            throw new InvalidOperationException($"Validation failed for '{kid}': {result.Reason}");
170	        }
171	
172	        KeyLifecycleTransitions.Ensure(meta.State, KeyLifecycleState.Validated);
173	        var next = meta with { State = KeyLifecycleState.Validated };
174	        await repo.UpsertAsync(next, ct);
175	        await repo.AddHistoryAsync(options.Realm, kid, meta.State.ToString(), next.State.ToString(), now, actor, null, ct);
176	        await audit.RecordAsync(new AuditEvent(actor, "key.validated", kid, now,
177	            new Dictionary<string, string?> { ["kid"] = kid }), ct);
178	        return ToDto(next);
179	    }
180	
181	    // ---- Activate (Validated -> Active): single Active per realm, previous -> InGrace ----
182	
183	    public async Task<Identity.Contracts.SigningKeyDto> ActivateAsync(string kid, string actor, string? idempotencyKey, CancellationToken ct)
184	    {
185	        // Idempotency: same key within the same logical operation returns prior outcome.
186	        if (!string.IsNullOrWhiteSpace(idempotencyKey))
187	        {
188	            var prior = await repo.GetOperationByIdempotencyAsync(options.Realm, idempotencyKey, ct);
189	            if (prior is not null && prior.Status == SagaStatus.Completed && prior.TargetKid == kid)
190	            {
191	                var existing = await repo.GetAsync(options.Realm, kid, ct);
192	                if (existing is not null) return ToDto(existing);
193	            }
194	        }
195	
196	        var meta = await repo.GetAsync(options.Realm, kid, ct)
197	            ?? throw new KeyNotFoundException($"Key '{kid}' not found.");
198	        if (meta.State != KeyLifecycleState.Validated)
199	            throw new InvalidOperationException($"Key '{kid}' is {meta.State}, expected Validated to activate.");
200	
201	        var handle = await rotationLock.TryAcquireAsync(options.Realm, options.RotationLockTtl, ct)
202	            ?? throw new InvalidOperationException($"Rotation lock for realm '{options.Realm}' is held by another operation.");
203	        try
204	        {
205	            // Re-read under lock to avoid double-activate races.
206	            var current = await repo.GetAsync(options.Realm, kid, ct) ?? meta;
207	            if (current.State == KeyLifecycleState.Active) return ToDto(current);
208	
209	            var opId = NewOpId();
210	            var now = clock.GetUtcNow();
211	            var op = new KeyRotationOperation(opId, idempotencyKey ?? opId, options.Realm, kid, null,
212	                KeyLifecycleState.Validated, SagaStatus.InProgress, now, now, actor, LockOwnerToken: handle.OwnerToken);
213	            await repo.UpsertOperationAsync(op, ct);
214	
215	            // Find previous Active.
216	            var all = await repo.ListAsync(options.Realm, 1, 200, ct);
217	            var previousActive = all.FirstOrDefault(x => x.State == KeyLifecycleState.Active);
218	
219	            await keycloak.ActivateAsync(options.Realm, current.KeycloakComponentId!, ct);
220	            var activated = current with { State = KeyLifecycleState.Active, ActivatedAt = now };
221	            await repo.UpsertAsync(activated, ct);
222	            await repo.AddHistoryAsync(options.Realm, kid, current.State.ToString(), activated.State.ToString(), now, actor, null, ct);
223	
224	            if (previousActive is not null)
225	            {
226	                await keycloak.PassivateAsync(options.Realm, previousActive.KeycloakComponentId!, ct);
227	                var passivated = previousActive with { State = KeyLifecycleState.InGrace, PassivatedAt = now };
228	                await repo.UpsertAsync(passivated, ct);
229	                await repo.AddHistoryAsync(options.Realm, previousActive.Kid, previousActive.State.ToString(), passivated.State.ToString(), now, actor, $"superseded by {kid}", ct);
230	                op = op with { PreviousKid = previousActive.Kid };
231	            }
232	
233	            // Convergence poll: new kid present, old kid still present.
234	            await PollConvergenceAsync(kid, previousActive?.Kid, ct);
235	
236	            op = op.Advanced(KeyLifecycleState.Active, SagaStatus.Completed, clock.GetUtcNow(), kid, op.PreviousKid);
237	            await repo.UpsertOperationAsync(op, ct);
238	            await audit.RecordAsync(new AuditEvent(actor, "key.activated", kid, now,
239	                new Dictionary<string, string?> { ["kid"] = kid, ["previous_kid"] = previousActive?.Kid }), ct);
240	            return ToDto(activated);
241	        }
242	        finally { await rotationLock.ReleaseAsync(handle, ct); }
243	    }
244	
245	    private async Task PollConvergenceAsync(string newKid, string? oldKid, CancellationToken ct)
246	    {
247	        var deadline = clock.GetUtcNow() + options.ConvergenceTimeout;
248	        while (clock.GetUtcNow() < deadline)
249	        {
250	            var jwks = await keycloak.GetJwksAsync(options.Realm, ct);
251	            var hasNew = jwks.Keys.Any(k => k.Kid == newKid);
252	            var hasOld = oldKid is null || jwks.Keys.Any(k => k.Kid == oldKid);
253	            if (hasNew && hasOld) return;
254	            await Task.Delay(options.ConvergencePollInterval, ct);
255	        }
256	        throw new TimeoutException($"JWKS convergence timed out waiting for kid '{newKid}'" + (oldKid is null ? "" : $" and retention of '{oldKid}'"));
257	    }
258	
259	    // ---- Rotate (full saga): ensure target kid, stage, validate, activate ----
260	
261	    public async Task<Identity.Contracts.RotationOperationDto> RotateAsync(
262	        Identity.Contracts.RotateRequest request, string actor, CancellationToken ct)
263	    {
264	        if (string.IsNullOrWhiteSpace(request.Reason)) throw new ArgumentException("Reason is required for rotation.", nameof(request));
265	        var idem = string.IsNullOrWhiteSpace(request.IdempotencyKey) ? Guid.NewGuid().ToString("N") : request.IdempotencyKey.Trim();
266	        var prior = await repo.GetOperationByIdempotencyAsync(options.Realm, idem, ct);
267	        if (prior is not null) return ToOpDto(prior);
268	
269	        // Ensure a VaultStored target exists.
270	        string targetKid = request.TargetKid?.Trim() ?? string.Empty;
271	        if (string.IsNullOrEmpty(targetKid))
272	        {
273	            var size = request.Size is 2048 or 3072 or 4096 ? (RsaKeySize)request.Size.Value : options.DefaultSize;
274	            var gen = await GenerateAsync(new Identity.Contracts.GenerateKeyRequest((int)size, Reason: request.Reason), actor, ct);
275	            targetKid = gen.Kid;
276	        }
277	        else
278	        {
279	            var existing = await repo.GetAsync(options.Realm, targetKid, ct)
280	                ?? throw new KeyNotFoundException($"Target kid '{targetKid}' not found.");
281	            if (existing.State != KeyLifecycleState.VaultStored && existing.State != KeyLifecycleState.Passive && existing.State != KeyLifecycleState.Validated)
282	                throw new InvalidOperationException($"Target '{targetKid}' is {existing.State}, expected VaultStored/Passive/Validated.");
283	        }
284	
285	        var opId = NewOpId();
286	        var now = clock.GetUtcNow();
287	        var op = new KeyRotationOperation(opId, idem, options.Realm, targetKid, null, KeyLifecycleState.VaultStored, SagaStatus.InProgress, now, now, actor);
288	        await repo.UpsertOperationAsync(op, ct);
289	
290	        try
291	        {
292	            var staged = await repo.GetAsync(options.Realm, targetKid, ct);
293	            if (staged!.State == KeyLifecycleState.VaultStored)
294	                await StageAsync(targetKid, actor, ct);
295	            staged = await repo.GetAsync(options.Realm, targetKid, ct);
296	            if (staged!.State == KeyLifecycleState.Passive)
297	                await ValidateAsync(targetKid, actor, ct);
298	            var activated = await ActivateAsync(targetKid, actor, idem + ":activate", ct);
299	            op = op.Advanced(KeyLifecycleState.Active, SagaStatus.Completed, clock.GetUtcNow(), targetKid, null);
300	            await repo.UpsertOperationAsync(op, ct);
301	            return ToOpDto(op);
302	        }
303	        catch (Exception ex)
304	        {
305	            op = op.Advanced(op.CurrentStep, SagaStatus.Failed, clock.GetUtcNow(), failure: ex.Message);
306	            await repo.UpsertOperationAsync(op, ct);
307	            throw;
308	        }
309	    }
310	
311	    public Task<Identity.Contracts.RotationOperationDto> EmergencyRotateAsync(
312	        Identity.Contracts.EmergencyRotateRequest request, string actor, CancellationToken ct)
313	        => RotateAsync(new Identity.Contracts.RotateRequest(request.Reason, request.IdempotencyKey, request.Size), actor, ct);
314	
315	    // ---- Rollback: re-activate previous, demote the failed new key (never destroy it) ----
316	
317	    public async Task<Identity.Contracts.RotationOperationDto> RollbackAsync(
318	        string failedKid, Identity.Contracts.RollbackRequest request, string actor, CancellationToken ct)
319	    {
320	        if (string.IsNullOrWhiteSpace(request.Reason)) throw new ArgumentException("Reason is required for rollback.", nameof(request));
321	        var failed = await repo.GetAsync(options.Realm, failedKid, ct)
322	            ?? throw new KeyNotFoundException($"Key '{failedKid}' not found.");
323	        // Find the most recent InGrace/Retiring that was superseded by failedKid.
324	        var all = await repo.ListAsync(options.Realm, 1, 200, ct);
325	        var previous = all.FirstOrDefault(x => x.State == KeyLifecycleState.InGrace || x.State == KeyLifecycleState.Retiring)
326	            ?? throw new InvalidOperationException("No rollback candidate found (no InGrace/Retiring key).");
327	
328	        var handle = await rotationLock.TryAcquireAsync(options.Realm, options.RotationLockTtl, ct)
329	            ?? throw new InvalidOperationException("Rotation lock is held.");
330	        try
331	        {
332	            var now = clock.GetUtcNow();
333	            await keycloak.ActivateAsync(options.Realm, previous.KeycloakComponentId!, ct);
334	            var reactivated = previous with { State = KeyLifecycleState.Active, ActivatedAt = now };
335	            await repo.UpsertAsync(reactivated, ct);
336	            await keycloak.PassivateAsync(options.Realm, failed.KeycloakComponentId!, ct);
337	            var demoted = failed with { State = KeyLifecycleState.Passive };
338	            await repo.UpsertAsync(demoted, ct);
339	            await repo.AddHistoryAsync(options.Realm, previous.Kid, previous.State.ToString(), reactivated.State.ToString(), now, actor, $"rollback from {failedKid}: {request.Reason}", ct);
340	            await repo.AddHistoryAsync(options.Realm, failedKid, failed.State.ToString(), demoted.State.ToString(), now, actor, $"rolled back: {request.Reason}", ct);
341	            var op = new KeyRotationOperation(NewOpId(), request.IdempotencyKey ?? NewOpId(), options.Realm, failedKid, previous.Kid,
342	                KeyLifecycleState.RollbackPending, SagaStatus.RolledBack, now, now, actor);
343	            await repo.UpsertOperationAsync(op, ct);
344	            await audit.RecordAsync(new AuditEvent(actor, "key.rollback", failedKid, now,
345	                new Dictionary<string, string?> { ["failed_kid"] = failedKid, ["restored_kid"] = previous.Kid }), ct);
346	            return ToOpDto(op);
347	        }
348	        finally { await rotationLock.ReleaseAsync(handle, ct); }
349	    }
350	
351	    // ---- Retire / Destroy ----
352	
353	    public async Task<Identity.Contracts.SigningKeyDto> RetireAsync(string kid, string actor, CancellationToken ct)
354	    {
355	        var meta = await repo.GetAsync(options.Realm, kid, ct) ?? throw new KeyNotFoundException($"Key '{kid}' not found.");
356	        if (meta.State != KeyLifecycleState.InGrace && meta.State != KeyLifecycleState.Retiring)
357	            throw new InvalidOperationException($"Key '{kid}' is {meta.State}, expected InGrace/Retiring to retire.");
358	        var now = clock.GetUtcNow();
359	        var eligibleAt = (meta.PassivatedAt ?? meta.ActivatedAt ?? meta.CreatedAt) + options.GracePeriod;
360	        if (now < eligibleAt)
361	            throw new InvalidOperationException($"Key '{kid}' is still in grace until {eligibleAt:O}.");
362	        await keycloak.DisableAsync(options.Realm, meta.KeycloakComponentId!, ct);
363	        var next = meta with { State = KeyLifecycleState.Retired, RetiredAt = now };
364	        await repo.UpsertAsync(next, ct);
365	        await repo.AddHistoryAsync(options.Realm, kid, meta.State.ToString(), next.State.ToString(), now, actor, null, ct);
366	        return ToDto(next);
367	    }
368	
369	    public async Task DestroyAsync(string kid, Identity.Contracts.DestroyRequest request, string actor, CancellationToken ct)
370	    {
371	        if (request.ConfirmKid != kid) throw new ArgumentException("ConfirmKid must equal the target kid.", nameof(request));
372	        var meta = await repo.GetAsync(options.Realm, kid, ct) ?? throw new KeyNotFoundException($"Key '{kid}' not found.");
373	        var assessment = await safety.AssessAsync(options.Realm, kid, ct);
374	        if (!assessment.Safe)
375	            throw new InvalidOperationException($"Destroy blocked for '{kid}': {string.Join("; ", assessment.BlockingReasons)}");
376	        var now = clock.GetUtcNow();
377	        await vault.DestroyAsync(kid, ct);
378	        if (meta.KeycloakComponentId is not null)
379	            await keycloak.RemoveAsync(options.Realm, meta.KeycloakComponentId, ct);
380	        var next = meta with { State = KeyLifecycleState.Destroyed, DestroyedAt = now };
381	        await repo.UpsertAsync(next, ct);
382	        await repo.AddHistoryAsync(options.Realm, kid, meta.State.ToString(), next.State.ToString(), now, actor, request.Reason, ct);
383	        await audit.RecordAsync(new AuditEvent(actor, "key.destroyed", kid, now,
384	            new Dictionary<string, string?> { ["kid"] = kid }), ct);
385	    }
386	
387	    // ---- Reads ----
388	
389	    public async Task<Identity.Contracts.SigningKeyListDto> ListAsync(int page, int pageSize, CancellationToken ct)
390	    {
391	        var items = await repo.ListAsync(options.Realm, page, pageSize, ct);
392	        var total = await repo.CountAsync(options.Realm, ct);
393	        return new(items.Select(ToDto).ToArray(), page, pageSize, total);
394	    }
