396	    public async Task<Identity.Contracts.SigningKeyDetailDto> GetAsync(string kid, CancellationToken ct)
397	    {
398	        var meta = await repo.GetAsync(options.Realm, kid, ct) ?? throw new KeyNotFoundException($"Key '{kid}' not found.");
399	        var publicPem = (await vault.ReadPublicAsync(kid, ct))?.PublicPem ?? string.Empty;
400	        var jwks = await keycloak.GetJwksAsync(options.Realm, ct);
401	        var entry = jwks.Keys.FirstOrDefault(k => k.Kid == kid);
402	        return new(ToDto(meta), entry is not null, entry is not null ? "match" : null);
