405	    public Task<IReadOnlyCollection<Identity.Contracts.KeyHistoryEntryDto>> HistoryAsync(string kid, CancellationToken ct)
406	        => repo.GetHistoryAsync(options.Realm, kid, ct);
407	
408	    public async Task<Identity.Contracts.RotationStateDto> RotationStateAsync(CancellationToken ct)
409	    {
410	        var all = await repo.ListAsync(options.Realm, 1, 500, ct);
411	        var active = all.FirstOrDefault(x => x.State == KeyLifecycleState.Active)?.Kid;
412	        var passive = all.Where(x => x.State is KeyLifecycleState.Passive or KeyLifecycleState.Validated or KeyLifecycleState.InGrace).Select(x => x.Kid).ToArray();
413	        var disabled = all.Where(x => x.State is KeyLifecycleState.Disabled or KeyLifecycleState.Retired).Select(x => x.Kid).ToArray();
414	        var inflight = await repo.ListInFlightAsync(options.Realm, ct);
415	        return new(options.Realm, active, passive, disabled, inflight.Select(ToOpDto).ToArray(), clock.GetUtcNow());
416	    }
