2	using Identity.Application;
3	using Identity.Domain;
4	
5	namespace Identity.Infrastructure;
6	
7	/// <summary>
8	/// Cross-cutting, non-secret infrastructure helpers shared by the Keycloak, external-SSO and
9	/// Redis adapters.
10	/// </summary>
11	/// <remarks>
12	/// This file intentionally contains no password hashing, token minting, session handling or
13	/// signing-key storage. The facade never issues tokens and never holds private key material:
14	/// RSA signing and key rotation belong to Keycloak and Vault. What remains here is the
15	/// redaction and audit plumbing those adapters need so secrets never reach logs or the
16	/// facade metadata store.
17	/// </remarks>
18	public static partial class SecretRedaction
19	{
20	    private const string Mask = "[REDACTED]";
21	
22	    /// <summary>Claim, header and configuration keys whose values must never be emitted.</summary>
23	    private static readonly HashSet<string> SensitiveKeys = new(StringComparer.OrdinalIgnoreCase)
24	    {
25	        "authorization", "cookie", "password", "pwd", "secret", "client_secret", "token",
26	        "access_token", "refresh_token", "id_token", "external_token", "organization_token",
27	        "private_key", "privatekey", "pkcs8", "vault_token", "x-vault-token", "api_key", "apikey"
28	    };
29	
30	    [GeneratedRegex(
31	        "(?i)(authorization|cookie|password|secret|token|private[_-]?key|vault[_-]?token)\\s*[:=]\\s*\\S+",
32	        RegexOptions.Compiled)]
33	    private static partial Regex KeyValuePattern();
34	
35	    [GeneratedRegex(
36	        "(?i)\"(authorization|password|pwd|secret|client_secret|access_token|refresh_token|id_token|external_token|organization_token|private_key|vault_token)\"\\s*:\\s*\"[^\"]*\"",
37	        RegexOptions.Compiled)]
38	    private static partial Regex JsonPattern();
39	
40	    [GeneratedRegex(
41	        "(?i)(bearer|basic)\\s+[A-Za-z0-9\\-._~+/]+=*",
42	        RegexOptions.Compiled)]
43	    private static partial Regex SchemePattern();
44	
45	    [GeneratedRegex("eyJ[A-Za-z0-9_-]{8,}\\.[A-Za-z0-9_-]{8,}\\.[A-Za-z0-9_-]{8,}", RegexOptions.Compiled)]
46	    private static partial Regex CompactJwtPattern();
47	
48	    /// <summary>True when a key names a secret, regardless of casing or separator.</summary>
49	    public static bool IsSensitive(string? key)
50	        => !string.IsNullOrEmpty(key) && SensitiveKeys.Contains(key.Replace('-', '_'));
51	
52	    /// <summary>
53	    /// Strips bearer/basic credentials, compact JWTs and secret key/value pairs from a message.
54	    /// Apply to every log line that could carry an inbound token or Keycloak/Vault response.
55	    /// </summary>
56	    public static string Redact(string? message)
57	    {
58	        if (string.IsNullOrEmpty(message)) return string.Empty;
59	        var result = SchemePattern().Replace(message, _ => Mask);
60	        result = CompactJwtPattern().Replace(result, Mask);
61	        result = JsonPattern().Replace(result, m => MaskJson(m.Value));
62	        result = KeyValuePattern().Replace(result, m => MaskKeyValue(m.Value));
63	        return result;
64	    }
65	
66	    /// <summary>Redacts the values of sensitive entries while preserving their key names.</summary>
67	    public static IReadOnlyDictionary<string, string?> Redact(
68	        IReadOnlyDictionary<string, string?> details)
69	    {
70	        ArgumentNullException.ThrowIfNull(details);
71	        var redacted = new Dictionary<string, string?>(details.Count, StringComparer.Ordinal);
72	        foreach (var (key, value) in details)
73	            redacted[key] = IsSensitive(key) ? Mask : Redact(value);
74	        return redacted;
75	    }
76	
77	    private static string MaskJson(string match)
78	    {
79	        var separator = match.IndexOf(':');
80	        return separator < 0 ? Mask : string.Concat(match.AsSpan(0, separator + 1), " \"", Mask, "\"");
81	    }
82	
83	    private static string MaskKeyValue(string match)
84	    {
85	        var separator = match.IndexOfAny([':', '=']);
86	        return separator < 0
87	            ? Mask
88	            : string.Concat(match.AsSpan(0, separator + 1), match.Contains('=') ? "=" : " ", Mask);
89	    }
90	}
91	
92	/// <summary>
93	/// Default sink that redacts detail values before delegating. Registration, provisioning,
94	/// linking and permission changes are recorded here; passwords, raw tokens, private keys and
95	/// Vault secrets are never accepted.
96	/// </summary>
97	public sealed class RedactingAuditSink(IAuditSink inner) : IAuditSink
98	{
99	    public Task RecordAsync(AuditEvent auditEvent, CancellationToken cancellationToken)
100	    {
101	        ArgumentNullException.ThrowIfNull(auditEvent);
102	        var safe = new AuditEvent(
103	            SecretRedaction.Redact(auditEvent.Actor),
104	            auditEvent.Action,
105	            SecretRedaction.Redact(auditEvent.Target),
106	            auditEvent.OccurredAt,
107	            SecretRedaction.Redact(auditEvent.Details));
108	        return inner.RecordAsync(safe, cancellationToken);
109	    }
110	}
