        {
            var path = Path(kid);
            var req = new HttpRequestMessage(HttpMethod.Post, $"{_o.Address}/v1/{path}")
            { Content = JsonContent.Create(new { data = new { kid, realm, size = (int)size, private_pem = privatePem, public_pem = publicPem, fingerprint = publicFingerprint } }) };
            AddAuth(req);
            var res = await http.SendAsync(req, ct);
            res.EnsureSuccessStatusCode();
            var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
            var ver = doc.RootElement.TryGetProperty("data", out var d) && d.TryGetProperty("metadata", out var m) && m.TryGetProperty("version", out var v) ? v.GetInt32() : 1;
