    using Identity.Application;
    using Microsoft.Extensions.Caching.Distributed;
    using StackExchange.Redis;

    namespace Identity.Infrastructure.Redis;

    public sealed class RedisKeyRotationLock(IConnectionMultiplexer mux) : IKeyRotationLock
    {
        private readonly IDatabase _db = mux.GetDatabase();
        private static string Key(string realm) => $"identity:rotation:lock:{realm}";
        public async Task<RotationLockHandle?> TryAcquireAsync(string realm, TimeSpan ttl, CancellationToken ct)
        {
            var token = Guid.NewGuid().ToString("N");
            var ok = await _db.StringSetAsync(Key(realm), token, ttl, When.NotExists);
            return ok ? new RotationLockHandle(realm, token, DateTimeOffset.UtcNow) : null;
        }
        public async Task<bool> RenewAsync(RotationLockHandle handle, TimeSpan ttl, CancellationToken ct)
        {
            var cur = await _db.StringGetAsync(Key(handle.Realm));
            if (cur != handle.OwnerToken) return false;
            return await _db.KeyExpireAsync(Key(handle.Realm), ttl);
        }
        public async Task ReleaseAsync(RotationLockHandle handle, CancellationToken ct)
        {
            var cur = await _db.StringGetAsync(Key(handle.Realm));
            if (cur == handle.OwnerToken) await _db.KeyDeleteAsync(Key(handle.Realm));
        }
    }
    public sealed class InMemoryKeyRotationLock : IKeyRotationLock
    {
        private readonly System.Collections.Concurrent.ConcurrentDictionary<string,string> _locks = new();
        public Task<RotationLockHandle?> TryAcquireAsync(string realm, TimeSpan ttl, CancellationToken ct)
        {
            var t = Guid.NewGuid().ToString("N");
            return Task.FromResult(_locks.TryAdd($"lock:{realm}", t) ? new RotationLockHandle(realm, t, DateTimeOffset.UtcNow) : null);
        }
        public Task<bool> RenewAsync(RotationLockHandle handle, TimeSpan ttl, CancellationToken ct) => Task.FromResult(_locks.TryGetValue($"lock:{handle.Realm}", out var v) && v == handle.OwnerToken);
        public Task ReleaseAsync(RotationLockHandle handle, CancellationToken ct) { _locks.TryRemove($"lock:{handle.Realm}", out _); return Task.CompletedTask; }
    }
