    namespace Identity.Infrastructure;

    public sealed class KeyRetirementSafety(IKeyLifecycleRepository repo, KeyManagementOptions opts, TimeProvider clock) : IKeyRetirementSafety
    {
        public async Task<RetirementSafetyAssessment> AssessAsync(string realm, string kid, CancellationToken ct)
        {
            var reasons = new List<string>();
            var meta = await repo.GetAsync(realm, kid, ct);
            if (meta is null) return new RetirementSafetyAssessment(kid, false, ["key not found"]);
            if (meta.State == KeyLifecycleState.Active) reasons.Add("key is still Active");
            if (meta.State == KeyLifecycleState.Destroyed) reasons.Add("already Destroyed");
            if (meta.State is KeyLifecycleState.Generated or KeyLifecycleState.VaultStored or KeyLifecycleState.Passive or KeyLifecycleState.Validated)
                reasons.Add($"key in state {meta.State} is not eligible for destroy");
            var graceEnd = (meta.PassivatedAt ?? meta.ActivatedAt ?? meta.CreatedAt) + opts.GracePeriod + opts.RetentionAfterGrace;
            if (clock.GetUtcNow() < graceEnd) reasons.Add($"retention window not elapsed until {graceEnd:O}");
            return new RetirementSafetyAssessment(kid, reasons.Count == 0, reasons);
        }
    }
