message PermissionResponse { string name = 1; string description = 2; string service_id = 3; string service_version = 4; bool deprecated = 5; string keycloak_role_id = 6; }
message PermissionListResponse { repeated PermissionResponse items = 1; }
message PermissionDefinition { string name = 1; string description = 2; }
message PermissionManifestRequest { string service_id = 1; string service_version = 2; string manifest_version = 3; repeated PermissionDefinition permissions = 4; string manifest_hash = 5; string idempotency_key = 6; }
