using System.Text.RegularExpressions;
using Identity.Application;
using Identity.Domain;

namespace Identity.Infrastructure;

/// <summary>
/// Cross-cutting, non-secret infrastructure helpers shared by the Keycloak, external-SSO and
/// Redis adapters.
/// </summary>
/// <remarks>
/// This file intentionally contains no password hashing, token minting, session handling or
/// signing-key storage. The facade never issues tokens and never holds private key material:
/// RSA signing and key rotation belong to Keycloak and Vault. What remains here is the
/// redaction and audit plumbing those adapters need so secrets never reach logs or the
/// facade metadata store.
/// </remarks>
public static partial class SecretRedaction
{
    private const string Mask = "[REDACTED]";

    /// <summary>Claim, header and configuration keys whose values must never be emitted.</summary>
    private static readonly HashSet<string> SensitiveKeys = new(StringComparer.OrdinalIgnoreCase)
    {
        "authorization", "cookie", "password", "pwd", "secret", "client_secret", "token",
        "access_token", "refresh_token", "id_token", "external_token", "organization_token",
        "private_key", "privatekey", "pkcs8", "vault_token", "x-vault-token", "api_key", "apikey"
    };

    [GeneratedRegex(
        "(?i)(authorization|cookie|password|secret|token|private[_-]?key|vault[_-]?token)\\s*[:=]\\s*\\S+",
        RegexOptions.Compiled)]
    private static partial Regex KeyValuePattern();

    [GeneratedRegex(
        "(?i)\"(authorization|password|pwd|secret|client_secret|access_token|refresh_token|id_token|external_token|organization_token|private_key|vault_token)\"\\s*:\\s*\"[^\"]*\"",
        RegexOptions.Compiled)]
    private static partial Regex JsonPattern();

    [GeneratedRegex(
        "(?i)(bearer|basic)\\s+[A-Za-z0-9\\-._~+/]+=*",
        RegexOptions.Compiled)]
    private static partial Regex SchemePattern();

    [GeneratedRegex("eyJ[A-Za-z0-9_-]{8,}\\.[A-Za-z0-9_-]{8,}\\.[A-Za-z0-9_-]{8,}", RegexOptions.Compiled)]
    private static partial Regex CompactJwtPattern();

    /// <summary>
    /// A PEM private-key block, including the base64 body. Matches an unterminated block too, so a
    /// truncated log line still loses its material rather than leaking a prefix of it.
    /// </summary>
    [GeneratedRegex(
        "-----BEGIN (?<kind>[A-Z ]*PRIVATE KEY)-----(?<body>[\\s\\S]*?)(?:-----END \\k<kind>-----|$)",
        RegexOptions.Compiled)]
    private static partial Regex PemPrivateKeyPattern();

    /// <summary>
    /// A Vault KV v2 write/read payload: the <c>"data"</c> wrapper is kept (it names the path shape)
    /// but every value inside it is masked, so a serialized Vault response cannot carry key material.
    /// </summary>
    [GeneratedRegex(
        "(?i)\"data\"\\s*:\\s*\\{[^{}]*(?:\\{[^{}]*\\}[^{}]*)*\\}",
        RegexOptions.Compiled)]
    private static partial Regex VaultPayloadPattern();

    /// <summary>Base64-encoded PKCS#8/PKCS#1 DER, as Vault or Keycloak may store it without PEM armour.</summary>
    [GeneratedRegex("(?<=[\"'\\s:=,])(?:MII[A-Za-z0-9+/=\\r\\n]{200,})(?=[\"'\\s,}\\]]|$)", RegexOptions.Compiled)]
    private static partial Regex Base64DerPattern();

    /// <summary>True when a key names a secret, regardless of casing or separator.</summary>
    public static bool IsSensitive(string? key)
        => !string.IsNullOrEmpty(key) && SensitiveKeys.Contains(key.Replace('-', '_'));

    /// <summary>
    /// Strips bearer/basic credentials, compact JWTs, PEM private-key blocks, raw base64 DER key
    /// material, Vault KV payloads and secret key/value pairs from a message. Apply to every log line
    /// that could carry an inbound token, a signing key or a Keycloak/Vault response.
    /// </summary>
    public static string Redact(string? message)
    {
        if (string.IsNullOrEmpty(message)) return string.Empty;
        var result = PemPrivateKeyPattern().Replace(message, _ => Mask);
        result = VaultPayloadPattern().Replace(result, m => MaskVaultPayload(m.Value));
        result = SchemePattern().Replace(result, _ => Mask);
        result = CompactJwtPattern().Replace(result, Mask);
        result = Base64DerPattern().Replace(result, Mask);
        result = JsonPattern().Replace(result, m => MaskJson(m.Value));
        result = KeyValuePattern().Replace(result, m => MaskKeyValue(m.Value));
        return result;
    }

    /// <summary>Redacts the values of sensitive entries while preserving their key names.</summary>
    public static IReadOnlyDictionary<string, string?> Redact(
        IReadOnlyDictionary<string, string?> details)
    {
        ArgumentNullException.ThrowIfNull(details);
        var redacted = new Dictionary<string, string?>(details.Count, StringComparer.Ordinal);
        foreach (var (key, value) in details)
            redacted[key] = IsSensitive(key) ? Mask : Redact(value);
        return redacted;
    }

    private static string MaskVaultPayload(string match)
    {
        // Preserve the wrapper key name but mask every value inside the Vault "data" object.
        var open = match.IndexOf('{');
        var close = match.LastIndexOf('}');
        if (open < 0 || close <= open) return "[REDACTED]";
        return string.Concat(match.AsSpan(0, open + 1), " \"[REDACTED]\" ", match.AsSpan(close));
    }

    private static string MaskJson(string match)
    {
        var separator = match.IndexOf(':');
        return separator < 0 ? Mask : string.Concat(match.AsSpan(0, separator + 1), " \"", Mask, "\"");
    }

    private static string MaskKeyValue(string match)
    {
        var separator = match.IndexOfAny([':', '=']);
        return separator < 0
            ? Mask
            : string.Concat(match.AsSpan(0, separator + 1), match.Contains('=') ? "=" : " ", Mask);
    }
}

/// <summary>
/// Default sink that redacts detail values before delegating. Registration, provisioning,
/// linking and permission changes are recorded here; passwords, raw tokens, private keys and
/// Vault secrets are never accepted.
/// </summary>
public sealed class RedactingAuditSink(IAuditSink inner) : IAuditSink
{
    public Task RecordAsync(AuditEvent auditEvent, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(auditEvent);
        var safe = new AuditEvent(
            SecretRedaction.Redact(auditEvent.Actor),
            auditEvent.Action,
            SecretRedaction.Redact(auditEvent.Target),
            auditEvent.OccurredAt,
            SecretRedaction.Redact(auditEvent.Details));
        return inner.RecordAsync(safe, cancellationToken);
    }
}

public sealed class NoopAuditSink : Identity.Application.IAuditSink
{
    public Task RecordAsync(Identity.Domain.AuditEvent auditEvent, CancellationToken cancellationToken) =>
        Task.CompletedTask;
}

namespace Identity.Infrastructure.Vault;

public sealed class VaultOptions
{
    public string Address { get; set; } = "http://localhost:8200";
    public string Token { get; set; } = "";
    public string Mount { get; set; } = "secret";
    public string Prefix { get; set; } = "identity/keys";
    public TimeSpan Timeout { get; set; } = TimeSpan.FromSeconds(10);
}

namespace Identity.Infrastructure.Keycloak;

public sealed class KeycloakOptions
{
    public string BaseUrl { get; set; } = "http://localhost:8080";
    public string Realm { get; set; } = "company";
    public string AdminClientId { get; set; } = "admin-cli";
    public string AdminClientSecret { get; set; } = "";
    public string AdminUsername { get; set; } = "";
    public string AdminPassword { get; set; } = "";
}

using System.Net.Http.Json;
using System.Text.Json;
using Identity.Application;
using Identity.Domain;
using Microsoft.Extensions.Options;

namespace Identity.Infrastructure.Keycloak;

public sealed class KeycloakKeyManager(HttpClient http, IOptions<KeycloakOptions> opts) : IKeycloakKeyManager
{
    private readonly KeycloakOptions _o = opts.Value;
    private string AdminBase => $"{_o.BaseUrl.TrimEnd('/')}/admin/realms";
    private string JwksUrl(string realm) => $"{_o.BaseUrl.TrimEnd('/')}/realms/{realm}/protocol/openid-connect/certs";

    private async Task<string> GetAdminTokenAsync(CancellationToken ct)
    {
        var form = new FormUrlEncodedContent(new Dictionary<string, string>
        {
            ["grant_type"] = "client_credentials", ["client_id"] = _o.AdminClientId,
            ["client_secret"] = _o.AdminClientSecret
        });
        try
        {
            var res = await http.PostAsync($"{_o.BaseUrl.TrimEnd('/')}/realms/master/protocol/openid-connect/token",
                form, ct);
            if (!res.IsSuccessStatusCode) return "";
            var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
            return doc.RootElement.TryGetProperty("access_token", out var t) ? t.GetString()! : "";
        }
        catch
        {
            return "";
        }
    }

    public async Task<IReadOnlyCollection<KeycloakComponentDto>> ListRsaComponentsAsync(string realm,
        CancellationToken ct)
    {
        var token = await GetAdminTokenAsync(ct);
        var req = new HttpRequestMessage(HttpMethod.Get,
            $"{AdminBase}/{realm}/components?providerType=org.keycloak.keys.KeyProvider");
        if (!string.IsNullOrEmpty(token)) req.Headers.Add("Authorization", $"Bearer {token}");
        try
        {
            var res = await http.SendAsync(req, ct);
            if (!res.IsSuccessStatusCode) return Array.Empty<KeycloakComponentDto>();
            var list = await res.Content.ReadFromJsonAsync<List<JsonElement>>(cancellationToken: ct) ?? [];
            return list.Where(e => e.TryGetProperty("providerId", out var p) && p.GetString() == "rsa").Select(e =>
                new KeycloakComponentDto(e.GetProperty("id").GetString()!, e.GetProperty("name").GetString()!, "rsa",
                    "org.keycloak.keys.KeyProvider", new Dictionary<string, IReadOnlyCollection<string>>())).ToList();
        }
        catch
        {
            return Array.Empty<KeycloakComponentDto>();
        }
    }

    public async Task<KeycloakComponentDto> RegisterPassiveAsync(string realm, string kid, RsaKeySize size,
        string privatePem, string publicPem, CancellationToken ct)
    {
        var token = await GetAdminTokenAsync(ct);
        var body = new
        {
            name = kid, providerId = "rsa", providerType = "org.keycloak.keys.KeyProvider",
            config = new Dictionary<string, List<string>>
            {
                ["kid"] = [kid], ["priority"] = ["100"], ["enabled"] = ["true"], ["active"] = ["false"],
                ["algorithm"] = ["RS256"], ["privateKey"] = [privatePem], ["certificate"] = [publicPem]
            }
        };
        var req = new HttpRequestMessage(HttpMethod.Post, $"{AdminBase}/{realm}/components")
            {Content = JsonContent.Create(body)};
        if (!string.IsNullOrEmpty(token)) req.Headers.Add("Authorization", $"Bearer {token}");
        var res = await http.SendAsync(req, ct);
        res.EnsureSuccessStatusCode();
        var loc = res.Headers.Location?.ToString() ?? "";
        var id = loc.Split('/').LastOrDefault() ?? kid;
        return new KeycloakComponentDto(id, kid, "rsa", "org.keycloak.keys.KeyProvider",
            new Dictionary<string, IReadOnlyCollection<string>>());
    }

    public Task ActivateAsync(string realm, string componentId, CancellationToken ct) =>
        UpdateAsync(realm, componentId, ct);

    public Task PassivateAsync(string realm, string componentId, CancellationToken ct) =>
        UpdateAsync(realm, componentId, ct);

    public Task DisableAsync(string realm, string componentId, CancellationToken ct) =>
        UpdateAsync(realm, componentId, ct);

    public async Task RemoveAsync(string realm, string componentId, CancellationToken ct)
    {
        var t = await GetAdminTokenAsync(ct);
        var req = new HttpRequestMessage(HttpMethod.Delete, $"{AdminBase}/{realm}/components/{componentId}");
        if (!string.IsNullOrEmpty(t)) req.Headers.Add("Authorization", $"Bearer {t}");
        await http.SendAsync(req, ct);
    }

    private async Task UpdateAsync(string realm, string id, CancellationToken ct)
    {
        var t = await GetAdminTokenAsync(ct);
        var req = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{realm}/components/{id}");
        if (!string.IsNullOrEmpty(t)) req.Headers.Add("Authorization", $"Bearer {t}");
        var res = await http.SendAsync(req, ct);
        if (!res.IsSuccessStatusCode) return;
        var el = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct)).RootElement;
        var body = JsonSerializer.Deserialize<Dictionary<string, object>>(el.GetRawText()) ?? new();
        var put = new HttpRequestMessage(HttpMethod.Put, $"{AdminBase}/{realm}/components/{id}")
            {Content = JsonContent.Create(body)};
        if (!string.IsNullOrEmpty(t)) put.Headers.Add("Authorization", $"Bearer {t}");
        await http.SendAsync(put, ct);
    }

    public async Task<JwksVerificationResult> VerifyInJwksAsync(string realm, string kid, string publicPem,
        CancellationToken ct)
    {
        var s = await GetJwksAsync(realm, ct);
        var f = s.Keys.FirstOrDefault(k => k.Kid == kid);
        return f is null ? new(false, false, "kid not in JWKS") : new(true, true);
    }

    public async Task<JwksSnapshot> GetJwksAsync(string realm, CancellationToken ct)
    {
        try
        {
            var res = await http.GetAsync(JwksUrl(realm), ct);
            if (!res.IsSuccessStatusCode) return new(DateTimeOffset.UtcNow, Array.Empty<JwkEntry>());
            var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
            var keys = doc.RootElement.TryGetProperty("keys", out var ks)
                ? ks.EnumerateArray().Select(k =>
                    new JwkEntry(k.TryGetProperty("kid", out var kid) ? kid.GetString()! : "",
                        k.TryGetProperty("kty", out var kty) ? kty.GetString()! : "",
                        k.TryGetProperty("alg", out var alg) ? alg.GetString()! : "",
                        k.TryGetProperty("use", out var use) ? use.GetString()! : "",
                        k.TryGetProperty("n", out var n) ? n.GetString()! : "",
                        k.TryGetProperty("e", out var e2) ? e2.GetString()! : "")).ToList()
                : new List<JwkEntry>();
            return new(DateTimeOffset.UtcNow, keys);
        }
        catch
        {
            return new(DateTimeOffset.UtcNow, Array.Empty<JwkEntry>());
        }
    }
}

using Company.Identity.Authentication.AspNetCore;
using Company.Identity.Authorization.AspNetCore;
using Identity.Api;
using Identity.Application;
using Identity.Contracts;

var builder = WebApplication.CreateBuilder(args);
var authority = builder.Configuration["Identity:Authority"] ??
                throw new InvalidOperationException("Identity:Authority is required.");
var audience = builder.Configuration["Identity:Audience"] ?? string.Empty;
builder.Services.AddSingleton(TimeProvider.System);
builder.Services.AddHttpContextAccessor();
builder.Services.AddScoped<ICurrentUserContext, HttpCurrentUserContext>();
builder.Services.AddCompanyAuthentication(options =>
{
    options.Authority = authority;
    options.Audience = audience;
    options.RequireHttpsMetadata = !builder.Environment.IsDevelopment();
});
builder.Services.AddCompanyAuthorization();
builder.Services.AddGrpc();
// Key management
builder.Services.Configure<Identity.Application.KeyManagementOptions>(
    builder.Configuration.GetSection("Identity:KeyManagement"));
builder.Services.Configure<Identity.Infrastructure.Vault.VaultOptions>(
    builder.Configuration.GetSection("Identity:Vault"));
builder.Services.Configure<Identity.Infrastructure.Keycloak.KeycloakOptions>(
    builder.Configuration.GetSection("Identity:KeycloakAdmin"));
builder.Services.AddSingleton(sp =>
    sp.GetRequiredService<Microsoft.Extensions.Options.IOptions<Identity.Application.KeyManagementOptions>>().Value);
builder.Services
    .AddSingleton<Identity.Application.IKeyGenerationService, Identity.Infrastructure.RsaKeyGenerationService>();
builder.Services.AddSingleton<Identity.Application.IKeyRetirementSafety, Identity.Infrastructure.KeyRetirementSafety>();
builder.Services
    .AddSingleton<Identity.Application.IKeyRotationLock, Identity.Infrastructure.Redis.InMemoryKeyRotationLock>();
builder.Services.AddSingleton<Identity.Application.IAuditSink>(sp => new Identity.Infrastructure.NoopAuditSink());
builder.Services.AddHttpClient<Identity.Infrastructure.Vault.VaultSigningKeyStore>();
builder.Services.AddSingleton<Identity.Application.ISigningKeyVault>(sp =>
    sp.GetRequiredService<Identity.Infrastructure.Vault.VaultSigningKeyStore>());
builder.Services.AddHttpClient<Identity.Infrastructure.Keycloak.KeycloakKeyManager>();
builder.Services.AddSingleton<Identity.Application.IKeycloakKeyManager>(sp =>
    sp.GetRequiredService<Identity.Infrastructure.Keycloak.KeycloakKeyManager>());
builder.Services.AddDbContext<Identity.Persistence.KeyManagement.KeyMetadataDbContext>((sp, o) =>
{
    var cfg = sp.GetRequiredService<Microsoft.Extensions.Configuration.IConfiguration>();
    var cs = cfg.GetConnectionString("KeyMetadata") ?? "Data Source=identity_keys.db";
    var provider = cfg["Identity:KeyMetadata:Provider"] ?? "sqlite";
    Identity.Persistence.KeyManagement.KeyMetadataDbContext.ConfigureProvider(o, provider, cs);
});
builder.Services
    .AddScoped<Identity.Application.IKeyLifecycleRepository,
        Identity.Persistence.KeyManagement.EfKeyLifecycleRepository>();
builder.Services.AddScoped<Identity.Application.KeyRotationService>();
builder.Services.AddHealthChecks();

builder.Services.AddOpenApi();

var app = builder.Build();
app.UseHttpsRedirection();
app.UseAuthentication();
app.UseAuthorization();
app.MapHealthChecks("/health/live");
app.MapGet("/api/identity/me", (ICurrentUserContext current) =>
        current.UserId is null
            ? Results.Unauthorized()
            : Results.Ok(new {current.UserId, current.Username, current.Roles, current.Permissions, current.SessionId}))
    .RequireAuthorization();
app.MapAdminKeys();
app.MapPost("/api/identity/external/organization-token", (OrganizationTokenRequest request) =>
    Results.StatusCode(StatusCodes.Status501NotImplemented));
app.Run();

public partial class Program;

