using Identity.Application;
using Identity.Contracts;
using Identity.Domain;
using Microsoft.EntityFrameworkCore;

namespace Identity.Persistence.EntityFrameworkCore;

/// <summary>Application-port bridge over <see cref="IdentityDbContext"/> for permission registration/listing.</summary>
public sealed class EfPermissionRegistry(IdentityDbContext db, TimeProvider clock) : IPermissionRegistry
{
    public async Task<ManifestRegistrationResponse> RegisterAsync(PermissionManifestRequest manifest, string authenticatedServiceId,
        CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(manifest.ServiceId)) throw new ArgumentException("ServiceId required.", nameof(manifest));
        // Failure must not prevent app start — the store layer surfaces errors gracefully;
        // callers already swallow persistence faults. Here we persist or throw to be handled upstream.
        var existing = await db.Permissions.Where(p => p.ServiceName == manifest.ServiceId).ToListAsync(ct);
        var incomingNames = manifest.Permissions.Select(p => p.Name).ToHashSet(StringComparer.Ordinal);
        var deprecated = existing.Where(p => !incomingNames.Contains(p.Name)).ToList();
        foreach (var p in deprecated) p.Deprecate();

        foreach (var def in manifest.Permissions)
        {
            var cur = existing.SingleOrDefault(p => p.Name == def.Name);
            if (cur is null)
                await db.Permissions.AddAsync(new Permission(
                    PermissionId.New(), def.Name, manifest.ServiceId, string.Empty,
                    def.Description, manifest.ManifestVersion, clock.GetUtcNow()), ct);
            else
                cur.Update(string.Empty, def.Description, manifest.ManifestVersion);
        }

        // Track manifest version state.
        var state = await db.PermissionManifestStates.SingleOrDefaultAsync(s => s.ServiceId == manifest.ServiceId, ct);
        if (state is null)
            await db.PermissionManifestStates.AddAsync(new PermissionManifestState(
                manifest.ServiceId, manifest.ServiceId, manifest.ManifestVersion,
                manifest.ManifestHash, clock.GetUtcNow()), ct);
        else
            state.Accept(manifest.ServiceId, manifest.ManifestVersion, manifest.ManifestHash, clock.GetUtcNow());

        await db.SaveChangesAsync(ct);
        return new ManifestRegistrationResponse(manifest.ServiceId, manifest.ManifestVersion, manifest.ManifestHash, true,
            deprecated.Select(p => p.Name).ToList());
    }

    public async Task<IReadOnlyCollection<PermissionDto>> GetPermissionsAsync(string? serviceId, bool includeDeprecated,
        CancellationToken ct)
    {
        var q = db.Permissions.AsNoTracking().AsQueryable();
        if (!string.IsNullOrWhiteSpace(serviceId)) q = q.Where(p => p.ServiceName == serviceId);
        if (!includeDeprecated) q = q.Where(p => !p.IsDeprecated);
        var list = await q.ToListAsync(ct);
        return list.Select(p => new PermissionDto(p.Name, p.Description, p.ServiceName, p.Version, p.IsDeprecated)).ToList();
    }
}

