            Results.Ok(await svc.ListAsync(page ?? 1, pageSize ?? 20, ct))).RequireAuthorization(KeyPermissions.View);
        g.MapGet("/{kid}", async (string kid, KeyRotationService svc, CancellationToken ct) =>
        {
