                    Results.Ok(await svc.ValidateAsync(kid, ctx.User.Identity?.Name ?? "admin", ct)))
            .RequireAuthorization(KeyPermissions.Validate);
        g.MapPost("/{kid}/activate", async (string kid, string? idempotencyKey, KeyRotationService svc, HttpContext ctx,
                    CancellationToken ct) =>
                Results.Ok(await svc.ActivateAsync(kid, ctx.User.Identity?.Name ?? "admin", idempotencyKey, ct)))
            .RequireAuthorization(KeyPermissions.Activate);
        g.MapPost("/{kid}/retire", async (string kid, KeyRotationService svc, HttpContext ctx, CancellationToken ct) =>
                Results.Ok(await svc.RetireAsync(kid, ctx.User.Identity?.Name ?? "admin", ct)))
            .RequireAuthorization(KeyPermissions.Retire);
