                    Results.Ok(await svc.EmergencyRotateAsync(req, ctx.User.Identity?.Name ?? "admin", ct)))
            .RequireAuthorization(KeyPermissions.EmergencyRotate);
        g.MapPost("/{kid}/rollback",
                async (string kid, RollbackRequest req, KeyRotationService svc, HttpContext ctx,
                        CancellationToken ct) =>
                    Results.Ok(await svc.RollbackAsync(kid, req, ctx.User.Identity?.Name ?? "admin", ct)))
            .RequireAuthorization(KeyPermissions.Rollback);
        g.MapGet("/{kid}/safety", async (string kid, KeyRotationService svc, CancellationToken ct) =>
            Results.Ok(await svc.AssessDestroySafetyAsync(kid, ct))).RequireAuthorization(KeyPermissions.View);
        return g;
