27	    private static async Task<IResult> Login(HttpContext ctx, IConfiguration cfg, IHttpClientFactory httpFactory, CancellationToken ct)
28	    {
29	        var form = await ReadFormAsync(ctx, ct);
30	        if (!form.TryGetValue("username", out var u) || !form.TryGetValue("password", out _))
31	            return Results.BadRequest(new ProblemResponse("validation_error", "username and password required", Correlation(ctx)));
32	        // Forward exactly as received to Keycloak to avoid re-interpreting credential handling.
33	        return await ProxyTokenAsync(cfg, httpFactory, form, ct, ctx);
34	    }
35	
36	    private static async Task<IResult> Refresh(HttpContext ctx, IConfiguration cfg, IHttpClientFactory httpFactory, CancellationToken ct)
37	    {
38	        var form = await ReadFormAsync(ctx, ct);
39	        form["grant_type"] = "refresh_token";
40	        return await ProxyTokenAsync(cfg, httpFactory, form, ct, ctx);
41	    }
42	
43	    private static async Task<IResult> Introspect(HttpContext ctx, IConfiguration cfg, IHttpClientFactory httpFactory, CancellationToken ct)
44	    {
45	        var form = await ReadFormAsync(ctx, ct);
46	        var realm = Realm(cfg);
47	        var baseUrl = BaseUrl(cfg);
48	        var token = form.TryGetValue("token", out var t) ? t : ctx.Request.Headers.Authorization.ToString().Replace("Bearer ", "");
49	        if (string.IsNullOrWhiteSpace(token))
50	            return Results.BadRequest(new ProblemResponse("validation_error", "token required", Correlation(ctx)));
51	        using var http = httpFactory.CreateClient();
52	        var req = new HttpRequestMessage(HttpMethod.Post, $"{baseUrl}/realms/{realm}/protocol/openid-connect/token/introspect")
53	        { Content = new FormUrlEncodedContent(form) };
54	        if (!string.IsNullOrWhiteSpace(form.GetValueOrDefault("client_id")) && form.TryGetValue("client_secret", out var cs))
55	            req.Headers.Authorization = new AuthenticationHeaderValue("Basic", Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes($"{form["client_id"]}:{cs}")));
56	        var res = await http.SendAsync(req, ct);
57	        var body = await res.Content.ReadAsStringAsync(ct);
58	        return Results.Content(body, "application/json", System.Text.Encoding.UTF8, (int)res.StatusCode);
59	    }
60	
61	    private static async Task<IResult> Logout(HttpContext ctx, IConfiguration cfg, IHttpClientFactory httpFactory, CancellationToken ct)
62	    {
63	        var form = await ReadFormAsync(ctx, ct);
64	        var realm = Realm(cfg);
65	        var baseUrl = BaseUrl(cfg);
66	        // Keycloak logout = token revocation; accept refresh_token or token.
67	        if (!form.ContainsKey("refresh_token") && form.TryGetValue("token", out var tok)) form["refresh_token"] = tok;
68	        using var http = httpFactory.CreateClient();
69	        var req = new HttpRequestMessage(HttpMethod.Post, $"{baseUrl}/realms/{realm}/protocol/openid-connect/logout")
70	        { Content = new FormUrlEncodedContent(form) };
71	        // Also try revocation endpoint for compatibility
72	        var res = await http.SendAsync(req, ct);
73	        if (!res.IsSuccessStatusCode)
74	        {
75	            var req2 = new HttpRequestMessage(HttpMethod.Post, $"{baseUrl}/realms/{realm}/protocol/openid-connect/revoke")
76	            { Content = new FormUrlEncodedContent(form) };
77	            res = await http.SendAsync(req2, ct);
78	        }
79	        var body = await res.Content.ReadAsStringAsync(ct);
80	        if (string.IsNullOrWhiteSpace(body)) return Results.Ok(new { success = res.IsSuccessStatusCode });
81	        return Results.Content(body, "application/json", System.Text.Encoding.UTF8, (int)res.StatusCode);
82	    }
83	
84	    private static async Task<IResult> ProxyTokenAsync(IConfiguration cfg, IHttpClientFactory fac, Dictionary<string, string> form, CancellationToken ct, HttpContext ctx)
85	    {
86	        var realm = Realm(cfg);
87	        var baseUrl = BaseUrl(cfg);
88	        using var http = fac.CreateClient();
89	        var res = await http.PostAsync($"{baseUrl}/realms/{realm}/protocol/openid-connect/token", new FormUrlEncodedContent(form), ct);
90	        var body = await res.Content.ReadAsStringAsync(ct);
91	        // Never log body (contains tokens). Redaction is enforced at caller logging boundaries.
92	        return Results.Content(body, "application/json", System.Text.Encoding.UTF8, (int)res.StatusCode);
93	    }
94	
95	    private static string Realm(IConfiguration c) => c["Identity:Keycloak:Realm"] ?? c["Identity:KeycloakAdmin:Realm"] ?? "company";
96	    private static string BaseUrl(IConfiguration c) => (c["Identity:Keycloak:BaseUrl"] ?? c["Identity:KeycloakAdmin:BaseUrl"] ?? "http://localhost:8080").TrimEnd('/');
97	    private static string Correlation(HttpContext c) => c.TraceIdentifier ?? Guid.NewGuid().ToString("N");
98	
99	    private static async Task<Dictionary<string, string>> ReadFormAsync(HttpContext ctx, CancellationToken ct)
100	    {
101	        if (ctx.Request.HasFormContentType)
102	        {
103	            await ctx.Request.ReadFormAsync(ct);
104	            return ctx.Request.Form.ToDictionary(k => k.Key, v => v.Value.ToString()!, StringComparer.Ordinal);
105	        }
106	        if (ctx.Request.ContentType?.Contains("application/json", StringComparison.OrdinalIgnoreCase) == true)
107	        {
108	            try
109	            {
110	                var doc = await JsonDocument.ParseAsync(ctx.Request.Body, cancellationToken: ct);
111	                return doc.RootElement.EnumerateObject().ToDictionary(p => p.Name, p => p.Value.GetString() ?? p.Value.ToString()!, StringComparer.Ordinal);
112	            }
113	            catch { }
114	        }
115	        var q = ctx.Request.Query.ToDictionary(k => k.Key, v => v.Value.ToString()!, StringComparer.Ordinal);
116	        return q;
117	    }
118	}

