4	using Identity.Contracts;
5	using Microsoft.Extensions.Options;
6	
7	namespace Identity.Infrastructure.Keycloak;
8	
9	/// <summary>
10	/// Keycloak Admin REST adapter that implements <see cref="IUserDirectory"/> and
11	/// <see cref="IRoleDirectory"/> against a single realm. The facade never invents
12	/// users locally — Keycloak is the only user store.
13	/// </summary>
14	public sealed class KeycloakDirectoryAdapter(HttpClient http, IOptions<KeycloakOptions> opts)
15	    : IUserDirectory, IRoleDirectory
16	{
17	    private readonly KeycloakOptions _o = opts.Value;
18	    private string AdminBase => $"{_o.BaseUrl.TrimEnd('/')}/admin/realms";
19	
20	    private async Task<string> GetAdminTokenAsync(CancellationToken ct)
21	    {
22	        if (!string.IsNullOrEmpty(_o.AdminClientSecret))
23	        {
24	            var form = new FormUrlEncodedContent(new Dictionary<string, string>
25	            {
26	                ["grant_type"] = "client_credentials",
27	                ["client_id"] = _o.AdminClientId,
28	                ["client_secret"] = _o.AdminClientSecret,
29	            });
30	            try
31	            {
32	                var res = await http.PostAsync(
33	                    $"{_o.BaseUrl.TrimEnd('/')}/realms/master/protocol/openid-connect/token", form, ct);
34	                if (!res.IsSuccessStatusCode) return string.Empty;
35	                var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
36	                return doc.RootElement.TryGetProperty("access_token", out var t) ? t.GetString() ?? string.Empty : string.Empty;
37	            }
38	            catch { return string.Empty; }
39	        }
40	        if (!string.IsNullOrEmpty(_o.AdminUsername) && !string.IsNullOrEmpty(_o.AdminPassword))
41	        {
42	            var form = new FormUrlEncodedContent(new Dictionary<string, string>
43	            {
44	                ["grant_type"] = "password",
45	                ["client_id"] = _o.AdminClientId,
46	                ["username"] = _o.AdminUsername,
47	                ["password"] = _o.AdminPassword,
48	            });
49	            try
50	            {
51	                var res = await http.PostAsync(
52	                    $"{_o.BaseUrl.TrimEnd('/')}/realms/master/protocol/openid-connect/token", form, ct);
53	                if (!res.IsSuccessStatusCode) return string.Empty;
54	                var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
55	                return doc.RootElement.TryGetProperty("access_token", out var t) ? t.GetString() ?? string.Empty : string.Empty;
56	            }
57	            catch { return string.Empty; }
58	        }
59	        return string.Empty;
60	    }
61	
62	    private void AttachAuth(HttpRequestMessage req, string token)
63	    {
64	        if (!string.IsNullOrEmpty(token)) req.Headers.Add("Authorization", $"Bearer {token}");
65	    }
66	
67	    private static UserDto MapUser(JsonElement e)
68	    {
69	        var id = e.TryGetProperty("id", out var pid) ? pid.GetString() ?? string.Empty : string.Empty;
70	        var username = e.TryGetProperty("username", out var p) ? p.GetString() ?? id : id;
71	        var enabled = e.TryGetProperty("enabled", out var en) && en.GetBoolean();
72	        string? displayName = null;
73	        string? fn2 = e.TryGetProperty("firstName", out var fnTmp) ? fnTmp.GetString() : null;
74	        string? ln2 = e.TryGetProperty("lastName", out var lnTmp) ? lnTmp.GetString() : null;
75	        if (!string.IsNullOrEmpty(fn2) || !string.IsNullOrEmpty(ln2))
76	            displayName = string.Join(" ", new[] { fn2, ln2 }.Where(s => !string.IsNullOrEmpty(s))).Trim();
77	        if (string.IsNullOrEmpty(displayName)) displayName = null;
78	        var attrs = new Dictionary<string, string[]>(StringComparer.Ordinal);
79	        if (e.TryGetProperty("attributes", out var at) && at.ValueKind == JsonValueKind.Object)
80	        {
81	            foreach (var prop in at.EnumerateObject())
82	                attrs[prop.Name] = prop.Value.ValueKind == JsonValueKind.Array
83	                    ? prop.Value.EnumerateArray().Select(v => v.GetString() ?? string.Empty).ToArray()
84	                    : [prop.Value.GetString() ?? string.Empty];
85	        }
86	        return new UserDto(id, username, displayName, enabled, attrs);
87	    }
88	
89	    private static RoleDto MapRole(JsonElement e)
90	    {
91	        var id = e.TryGetProperty("id", out var pid) ? pid.GetString() ?? string.Empty : string.Empty;
92	        var name = e.TryGetProperty("name", out var n) ? n.GetString() ?? string.Empty : string.Empty;
93	        var desc = e.TryGetProperty("description", out var d) ? d.GetString() : null;
94	        var clientId = e.TryGetProperty("containerId", out var c) ? c.GetString() : null;
95	        var composite = e.TryGetProperty("composite", out var comp) && comp.GetBoolean();
96	        return new RoleDto(id, name, desc, clientId, composite);
97	    }
98	
99	    public async Task<PagedResponse<UserDto>> GetUsersAsync(string? search, int page, int pageSize, CancellationToken ct)
100	    {
101	        page = Math.Max(1, page); pageSize = Math.Clamp(pageSize, 1, 100);
102	        var token = await GetAdminTokenAsync(ct);
103	        var first = (page - 1) * pageSize;
104	        var url = $"{AdminBase}/{_o.Realm}/users?first={first}&max={pageSize}";
105	        if (!string.IsNullOrWhiteSpace(search)) url += $"&search={Uri.EscapeDataString(search)}";
106	        var req = new HttpRequestMessage(HttpMethod.Get, url);
107	        AttachAuth(req, token);
108	        try
109	        {
110	            var res = await http.SendAsync(req, ct);
111	            if (!res.IsSuccessStatusCode) return new PagedResponse<UserDto>([], page, pageSize, 0);
112	            var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
113	            var items = doc.RootElement.ValueKind == JsonValueKind.Array
114	                ? doc.RootElement.EnumerateArray().Select(MapUser).ToList()
115	                : new List<UserDto>();
116	            return new PagedResponse<UserDto>(items, page, pageSize, null);
117	        }
118	        catch { return new PagedResponse<UserDto>([], page, pageSize, 0); }
119	    }
120	
121	    public async Task<UserDto?> GetUserAsync(string id, CancellationToken ct)
122	    {
123	        var token = await GetAdminTokenAsync(ct);
124	        var req = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{_o.Realm}/users/{Uri.EscapeDataString(id)}");
125	        AttachAuth(req, token);
126	        try
127	        {
128	            var res = await http.SendAsync(req, ct);
129	            if (!res.IsSuccessStatusCode) return null;
130	            var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
131	            return MapUser(doc.RootElement);
132	        }
133	        catch { return null; }
134	    }
135	
136	    public async Task<IReadOnlyCollection<RoleDto>> GetUserRolesAsync(string id, CancellationToken ct)
137	    {
138	        var token = await GetAdminTokenAsync(ct);
139	        var req = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{_o.Realm}/users/{Uri.EscapeDataString(id)}/role-mappings");
140	        AttachAuth(req, token);
141	        try
142	        {
143	            var res = await http.SendAsync(req, ct);
144	            if (!res.IsSuccessStatusCode) return [];
145	            var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
146	            var result = new List<RoleDto>();
147	            if (doc.RootElement.TryGetProperty("realmMappings", out var rm) && rm.ValueKind == JsonValueKind.Array)
148	                result.AddRange(rm.EnumerateArray().Select(MapRole));
149	            if (doc.RootElement.TryGetProperty("clientMappings", out var cm) && cm.ValueKind == JsonValueKind.Object)
150	                foreach (var prop in cm.EnumerateObject())
151	                    if (prop.Value.TryGetProperty("mappings", out var m) && m.ValueKind == JsonValueKind.Array)
152	                        result.AddRange(m.EnumerateArray().Select(MapRole));
153	            return result;
154	        }
155	        catch { return []; }
156	    }
157	
158	    public async Task<IReadOnlyCollection<PermissionDto>> GetUserPermissionsAsync(string id, CancellationToken ct)
159	    {
160	        // Permissions are modelled as roles in Keycloak for this facade; map them to PermissionDto by convention.
161	        var roles = await GetUserRolesAsync(id, ct);
162	        return roles.Select(r => new PermissionDto(r.Name, r.Description ?? r.Name, _o.Realm, string.Empty, false, r.Id)).ToList();
163	    }
164	
165	    public async Task<PagedResponse<RoleDto>> GetRolesAsync(string? clientId, int page, int pageSize, CancellationToken ct)
166	    {
167	        page = Math.Max(1, page); pageSize = Math.Clamp(pageSize, 1, 100);
168	        var token = await GetAdminTokenAsync(ct);
169	        var first = (page - 1) * pageSize;
170	        string url = string.IsNullOrWhiteSpace(clientId)
171	            ? $"{AdminBase}/{_o.Realm}/roles?first={first}&max={pageSize}"
172	            : $"{AdminBase}/{_o.Realm}/clients/{Uri.EscapeDataString(clientId)}/roles?first={first}&max={pageSize}";
173	        var req = new HttpRequestMessage(HttpMethod.Get, url);
174	        AttachAuth(req, token);
175	        try
176	        {
177	            var res = await http.SendAsync(req, ct);
178	            if (!res.IsSuccessStatusCode) return new PagedResponse<RoleDto>([], page, pageSize, 0);
179	            var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
180	            var items = doc.RootElement.ValueKind == JsonValueKind.Array
181	                ? doc.RootElement.EnumerateArray().Select(MapRole).ToList()
182	                : new List<RoleDto>();
183	            return new PagedResponse<RoleDto>(items, page, pageSize, null);
