using System.Collections.Concurrent;
using Identity.Application;
using Identity.Contracts;

namespace Identity.Api;

/// <summary>
/// In-memory permission catalog that satisfies <see cref="IPermissionRegistry"/> without
/// requiring the facade metadata DB to be available at startup. Missing permissions are
/// soft-deprecated, never deleted — matching the contract expected of an EF-backed store.
/// Backed by a concurrent dictionary so it works in single-node and test hosts.
/// </summary>
public sealed class InMemoryPermissionRegistry : IPermissionRegistry
{
    private readonly ConcurrentDictionary<string, PermissionDto> _perms = new(StringComparer.Ordinal);

    private readonly ConcurrentDictionary<string, (string Version, string Hash)> _manifests =
        new(StringComparer.Ordinal);

    public Task<ManifestRegistrationResponse> RegisterAsync(PermissionManifestRequest manifest,
        string authenticatedServiceId, CancellationToken ct)
    {
        var incoming = manifest.Permissions.Select(p => p.Name).ToHashSet(StringComparer.Ordinal);
        var already = _perms.Values.Where(p => p.ServiceId == manifest.ServiceId).ToList();
        var deprecated = already.Where(p => !incoming.Contains(p.Name)).Select(p => p.Name).ToList();
        foreach (var name in deprecated)
            if (_perms.TryGetValue(name, out var cur))
                _perms[name] = cur with { Deprecated = true };
        foreach (var d in manifest.Permissions)
        {
            _perms.AddOrUpdate(d.Name,
                _ => new PermissionDto(d.Name, d.Description, manifest.ServiceId, manifest.ManifestVersion, false),
                (_, cur) => cur with
                {
                    Description = d.Description, ServiceVersion = manifest.ManifestVersion, Deprecated = false
                });
        }

        _manifests[manifest.ServiceId] = (manifest.ManifestVersion, manifest.ManifestHash);
        return Task.FromResult(new ManifestRegistrationResponse(manifest.ServiceId, manifest.ManifestVersion,
            manifest.ManifestHash, true, deprecated));
    }

    public Task<IReadOnlyCollection<PermissionDto>> GetPermissionsAsync(string? serviceId, bool includeDeprecated,
        CancellationToken ct)
    {
        IEnumerable<PermissionDto> q = _perms.Values;
        if (!string.IsNullOrWhiteSpace(serviceId)) q = q.Where(p => p.ServiceId == serviceId);
        if (!includeDeprecated) q = q.Where(p => !p.Deprecated);
        return Task.FromResult<IReadOnlyCollection<PermissionDto>>(q.ToList());
    }
}#pragma warning disable ASPDEPR002
using Identity.Application;
using Identity.Contracts;

namespace Identity.Api;

public static class PermissionEndpoints
{
    public static RouteGroupBuilder MapPermissions(this IEndpointRouteBuilder app)
    {
        var g = app.MapGroup("/api/identity/permissions").WithTags("Permissions");
        g.MapPost("/register", async (PermissionManifestRequest req, PermissionRegistrationService svc, HttpContext ctx,
                CancellationToken ct) =>
            {
                var serviceId = ctx.User.FindFirst("client_id")?.Value ??
                                ctx.User.FindFirst("azp")?.Value ?? req.ServiceId;
                var res = await svc.RegisterAsync(req, serviceId, ct);
                return Results.Ok(res);
            }).RequireAuthorization("Identity.Permissions.Register")
            .WithName("RegisterPermissions").Produces<ManifestRegistrationResponse>(200)
            .WithOpenApi(o =>
            {
                o.Summary = "Register/refresh a service permission manifest";
                o.Description =
                    "Failure here must not prevent app start. Missing permissions are deprecated, never auto-deleted.";
                return o;
            });
        return g;
    }
}===
using System.Reflection;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Company.Identity.Abstractions;

namespace Company.Identity.PermissionRegistration;

public sealed class PermissionRegistrationOptions
{
    public required Uri IdentityServer { get; set; }
    public required string ServiceName { get; set; }
    public string ServiceId { get; set; } = string.Empty;
    public string ServiceVersion { get; set; } = "0.0.0";
    public string ManifestVersion { get; set; } = "1";
    public TimeSpan InitialRetryDelay { get; set; } = TimeSpan.FromSeconds(2);
    public int MaximumRetries { get; set; } = 8;
}

public sealed record PermissionManifest(
    string ServiceId,
    string ServiceVersion,
    string ManifestVersion,
    IReadOnlyCollection<PermissionDescriptor> Permissions,
    string ManifestHash)
{
    public static PermissionManifest Create(PermissionRegistrationOptions options, Assembly assembly)
    {
        var permissions = assembly.GetTypes().SelectMany(type => type
                .GetCustomAttributes<RequirePermissionAttribute>(true)
                .Select(attribute => new PermissionDescriptor(attribute.Name,
                    $"Permission for {type.FullName ?? type.Name}", type.Namespace ?? string.Empty))
                .Concat(type
                    .GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance |
                                BindingFlags.Static)
                    .SelectMany(method => method.GetCustomAttributes<RequirePermissionAttribute>(true)
                        .Select(attribute => new PermissionDescriptor(attribute.Name,
                            $"Permission for {method.DeclaringType?.FullName ?? type.Name}.{method.Name}",
                            type.Namespace ?? string.Empty)))))
            .Where(x => !string.IsNullOrWhiteSpace(x.Name)).DistinctBy(x => x.Name, StringComparer.Ordinal)
            .OrderBy(x => x.Name, StringComparer.Ordinal).ToArray();
        var serviceId = string.IsNullOrWhiteSpace(options.ServiceId) ? options.ServiceName : options.ServiceId;
        var canonical = JsonSerializer.Serialize(new
        {
            serviceId, serviceVersion = options.ServiceVersion, manifestVersion = options.ManifestVersion, permissions
        });
        var hash = "sha256:" +
                   Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(canonical))).ToLowerInvariant();
        return new(serviceId, options.ServiceVersion, options.ManifestVersion, permissions, hash);
    }
}===
