using System.Reflection;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Company.Identity.Abstractions;

namespace Company.Identity.PermissionRegistration;

public sealed class PermissionRegistrationOptions
{
    public required Uri IdentityServer { get; set; }
    public required string ServiceName { get; set; }
    public string ServiceId { get; set; } = string.Empty;
    public string ServiceVersion { get; set; } = "0.0.0";
    public string ManifestVersion { get; set; } = "1";
    public TimeSpan InitialRetryDelay { get; set; } = TimeSpan.FromSeconds(2);
    public int MaximumRetries { get; set; } = 8;
}

public sealed record PermissionManifest(
    string ServiceId,
    string ServiceVersion,
    string ManifestVersion,
    IReadOnlyCollection<PermissionDescriptor> Permissions,
    string ManifestHash)
{
    public static PermissionManifest Create(PermissionRegistrationOptions options, Assembly assembly)
    {
        var permissions = assembly.GetTypes().SelectMany(type => type
                .GetCustomAttributes<RequirePermissionAttribute>(true)
                .Select(attribute => new PermissionDescriptor(attribute.Name,
                    $"Permission for {type.FullName ?? type.Name}", type.Namespace ?? string.Empty))
                .Concat(type
                    .GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance |
                                BindingFlags.Static)
                    .SelectMany(method => method.GetCustomAttributes<RequirePermissionAttribute>(true)
                        .Select(attribute => new PermissionDescriptor(attribute.Name,
                            $"Permission for {method.DeclaringType?.FullName ?? type.Name}.{method.Name}",
                            type.Namespace ?? string.Empty)))))
            .Where(x => !string.IsNullOrWhiteSpace(x.Name)).DistinctBy(x => x.Name, StringComparer.Ordinal)
            .OrderBy(x => x.Name, StringComparer.Ordinal).ToArray();
        var serviceId = string.IsNullOrWhiteSpace(options.ServiceId) ? options.ServiceName : options.ServiceId;
        var canonical = JsonSerializer.Serialize(new
        {
            serviceId, serviceVersion = options.ServiceVersion, manifestVersion = options.ManifestVersion, permissions
        });
        var hash = "sha256:" +
                   Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(canonical))).ToLowerInvariant();
        return new(serviceId, options.ServiceVersion, options.ManifestVersion, permissions, hash);
    }
}

using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using Identity.Application;
using Identity.Domain;
using Microsoft.Extensions.Options;

namespace Identity.Infrastructure.Keycloak;

public sealed class KeycloakKeyManager(HttpClient http, IOptions<KeycloakOptions> opts) : IKeycloakKeyManager
{
    private readonly KeycloakOptions _o = opts.Value;
    private string AdminBase => $"{_o.BaseUrl.TrimEnd('/')}/admin/realms";
    private string JwksUrl(string realm) => $"{_o.BaseUrl.TrimEnd('/')}/realms/{realm}/protocol/openid-connect/certs";

    private async Task<string> GetAdminTokenAsync(CancellationToken ct)
    {
        // Same bootstrap as KeycloakDirectoryAdapter: client credentials when a secret is configured,
        // otherwise the dev-only resource-owner grant against the master realm.
        Dictionary<string, string> formValues;
        if (!string.IsNullOrEmpty(_o.AdminClientSecret))
            formValues = new Dictionary<string, string>
            {
                ["grant_type"] = "client_credentials", ["client_id"] = _o.AdminClientId,
                ["client_secret"] = _o.AdminClientSecret
            };
        else if (!string.IsNullOrEmpty(_o.AdminUsername) && !string.IsNullOrEmpty(_o.AdminPassword))
            formValues = new Dictionary<string, string>
            {
                ["grant_type"] = "password", ["client_id"] = _o.AdminClientId,
                ["username"] = _o.AdminUsername, ["password"] = _o.AdminPassword
            };
        else return "";
        var form = new FormUrlEncodedContent(formValues);
        try
        {
            var res = await http.PostAsync($"{_o.BaseUrl.TrimEnd('/')}/realms/master/protocol/openid-connect/token",
                form, ct);
            if (!res.IsSuccessStatusCode) return "";
            var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
            return doc.RootElement.TryGetProperty("access_token", out var t) ? t.GetString()! : "";
        }
        catch
        {
            return "";
        }
    }

    public async Task<IReadOnlyCollection<KeycloakComponentDto>> ListRsaComponentsAsync(string realm,
        CancellationToken ct)
    {
        var token = await GetAdminTokenAsync(ct);
        var req = new HttpRequestMessage(HttpMethod.Get,
            $"{AdminBase}/{realm}/components?providerType=org.keycloak.keys.KeyProvider");
        if (!string.IsNullOrEmpty(token)) req.Headers.Add("Authorization", $"Bearer {token}");
        try
        {
            var res = await http.SendAsync(req, ct);
            if (!res.IsSuccessStatusCode) return Array.Empty<KeycloakComponentDto>();
            var list = await res.Content.ReadFromJsonAsync<List<JsonElement>>(cancellationToken: ct) ?? [];
            return list.Where(e => e.TryGetProperty("providerId", out var p) && p.GetString() == "rsa").Select(e =>
                new KeycloakComponentDto(e.GetProperty("id").GetString()!, e.GetProperty("name").GetString()!, "rsa",
                    "org.keycloak.keys.KeyProvider", new Dictionary<string, IReadOnlyCollection<string>>())).ToList();
        }
        catch
        {
            return Array.Empty<KeycloakComponentDto>();
        }
    }

    public async Task<KeycloakComponentDto> RegisterPassiveAsync(string realm, string kid, RsaKeySize size,
        string privatePem, string publicPem, CancellationToken ct)
    {
        var token = await GetAdminTokenAsync(ct);
        var body = new
        {
            name = kid, providerId = "rsa", providerType = "org.keycloak.keys.KeyProvider",
            config = new Dictionary<string, List<string>>
            {
                ["kid"] = [kid], ["priority"] = ["100"], ["enabled"] = ["true"], ["active"] = ["false"],
                ["algorithm"] = ["RS256"], ["privateKey"] = [privatePem], ["certificate"] = [publicPem]
            }
        };
        var req = new HttpRequestMessage(HttpMethod.Post, $"{AdminBase}/{realm}/components")
            { Content = JsonContent.Create(body) };
        if (!string.IsNullOrEmpty(token)) req.Headers.Add("Authorization", $"Bearer {token}");
        var res = await http.SendAsync(req, ct);
        res.EnsureSuccessStatusCode();
        var loc = res.Headers.Location?.ToString() ?? "";
        var id = loc.Split('/').LastOrDefault() ?? kid;
        return new KeycloakComponentDto(id, kid, "rsa", "org.keycloak.keys.KeyProvider",
            new Dictionary<string, IReadOnlyCollection<string>>());
    }

    public Task ActivateAsync(string realm, string componentId, CancellationToken ct) =>
        PatchComponentConfigAsync(realm, componentId, cfg =>
        {
            SetConfig(cfg, "active", "true");
            SetConfig(cfg, "enabled", "true");
        }, ct);

    public Task PassivateAsync(string realm, string componentId, CancellationToken ct) =>
        PatchComponentConfigAsync(realm, componentId, cfg => SetConfig(cfg, "active", "false"), ct);

    public Task DisableAsync(string realm, string componentId, CancellationToken ct) =>
        PatchComponentConfigAsync(realm, componentId, cfg => SetConfig(cfg, "enabled", "false"), ct);

    // Keycloak MultiValuedHashMap config: every value is a JSON array of strings.
    private static void SetConfig(IDictionary<string, JsonNode?> cfg, string key, string value) =>
        cfg[key] = new JsonArray { JsonValue.Create(value) };

    public async Task RemoveAsync(string realm, string componentId, CancellationToken ct)
    {
        var t = await GetAdminTokenAsync(ct);
        var req = new HttpRequestMessage(HttpMethod.Delete, $"{AdminBase}/{realm}/components/{componentId}");
        if (!string.IsNullOrEmpty(t)) req.Headers.Add("Authorization", $"Bearer {t}");
        await http.SendAsync(req, ct);
    }

    /// <summary>
    /// Reads the component, mutates only the supplied <c>config</c> entries and writes it back —
    /// Keycloak's component PUT is a full replace, so a blind re-PUT of the GET body is a no-op.
    /// Never log the response body: it carries <c>config.privateKey</c>.
    /// </summary>
    private async Task PatchComponentConfigAsync(string realm, string id,
        Action<IDictionary<string, JsonNode?>> patch, CancellationToken ct)
    {
        var t = await GetAdminTokenAsync(ct);
        var req = new HttpRequestMessage(HttpMethod.Get, $"{AdminBase}/{realm}/components/{Uri.EscapeDataString(id)}");
        if (!string.IsNullOrEmpty(t)) req.Headers.Add("Authorization", $"Bearer {t}");
        var res = await http.SendAsync(req, ct);
        if (!res.IsSuccessStatusCode) return;
        var node = JsonNode.Parse(await res.Content.ReadAsStringAsync(ct));
        if (node is not JsonObject component) return;
        if (component["config"] is not JsonObject cfg)
        {
            cfg = new JsonObject();
            component["config"] = cfg;
        }

        patch(cfg);
        var put = new HttpRequestMessage(HttpMethod.Put, $"{AdminBase}/{realm}/components/{Uri.EscapeDataString(id)}")
            { Content = new StringContent(component.ToJsonString(), Encoding.UTF8, "application/json") };
        if (!string.IsNullOrEmpty(t)) put.Headers.Add("Authorization", $"Bearer {t}");
        await http.SendAsync(put, ct);
    }

    public async Task<JwksVerificationResult> VerifyInJwksAsync(string realm, string kid, string publicPem,
        CancellationToken ct)
    {
        var s = await GetJwksAsync(realm, ct);
        var f = s.Keys.FirstOrDefault(k => k.Kid == kid);
        return f is null ? new(false, false, "kid not in JWKS") : new(true, true);
    }

    public async Task<JwksSnapshot> GetJwksAsync(string realm, CancellationToken ct)
    {
        try
        {
            var res = await http.GetAsync(JwksUrl(realm), ct);
            if (!res.IsSuccessStatusCode) return new(DateTimeOffset.UtcNow, Array.Empty<JwkEntry>());
            var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
            var keys = doc.RootElement.TryGetProperty("keys", out var ks)
                ? ks.EnumerateArray().Select(k =>
                    new JwkEntry(k.TryGetProperty("kid", out var kid) ? kid.GetString()! : "",
                        k.TryGetProperty("kty", out var kty) ? kty.GetString()! : "",
                        k.TryGetProperty("alg", out var alg) ? alg.GetString()! : "",
                        k.TryGetProperty("use", out var use) ? use.GetString()! : "",
                        k.TryGetProperty("n", out var n) ? n.GetString()! : "",
                        k.TryGetProperty("e", out var e2) ? e2.GetString()! : "")).ToList()
                : new List<JwkEntry>();
            return new(DateTimeOffset.UtcNow, keys);
        }
        catch
        {
            return new(DateTimeOffset.UtcNow, Array.Empty<JwkEntry>());
        }
    }
}

using Company.Identity.Authentication.AspNetCore;
using Company.Identity.Authorization.AspNetCore;
using Identity.Api;
using Identity.Application;
using Identity.Contracts;

var builder = WebApplication.CreateBuilder(args);
var authority = builder.Configuration["Identity:Authority"] ??
                throw new InvalidOperationException("Identity:Authority is required.");
var audience = builder.Configuration["Identity:Audience"] ?? string.Empty;
builder.Services.AddSingleton(TimeProvider.System);
builder.Services.AddHttpContextAccessor();
builder.Services.AddHttpClient();
builder.Services.AddScoped<ICurrentUserContext, HttpCurrentUserContext>();
builder.Services.AddCompanyAuthentication(options =>
{
    options.Authority = authority;
    options.Audience = audience;
    options.RequireHttpsMetadata = !builder.Environment.IsDevelopment();
});
builder.Services.AddCompanyAuthorization();
builder.Services.AddGrpc();

// Key management
builder.Services.Configure<KeyManagementOptions>(builder.Configuration.GetSection("Identity:KeyManagement"));
builder.Services.Configure<Identity.Infrastructure.Vault.VaultOptions>(
    builder.Configuration.GetSection("Identity:Vault"));
builder.Services.Configure<Identity.Infrastructure.Keycloak.KeycloakOptions>(
    builder.Configuration.GetSection("Identity:KeycloakAdmin"));
builder.Services.AddSingleton(sp =>
    sp.GetRequiredService<Microsoft.Extensions.Options.IOptions<KeyManagementOptions>>().Value);
builder.Services.AddSingleton<IKeyGenerationService, Identity.Infrastructure.RsaKeyGenerationService>();
builder.Services.AddSingleton<IKeyRetirementSafety, Identity.Infrastructure.KeyRetirementSafety>();
builder.Services.AddSingleton<IKeyRotationLock, Identity.Infrastructure.Redis.InMemoryKeyRotationLock>();
builder.Services.AddSingleton<IAuditSink>(sp => new Identity.Infrastructure.NoopAuditSink());
builder.Services.AddHttpClient<Identity.Infrastructure.Vault.VaultSigningKeyStore>();
builder.Services.AddSingleton<ISigningKeyVault>(sp =>
    sp.GetRequiredService<Identity.Infrastructure.Vault.VaultSigningKeyStore>());
builder.Services.AddHttpClient<Identity.Infrastructure.Keycloak.KeycloakKeyManager>();
builder.Services.AddSingleton<IKeycloakKeyManager>(sp =>
    sp.GetRequiredService<Identity.Infrastructure.Keycloak.KeycloakKeyManager>());

// Directory + permissions — Keycloak is source of truth; facade registry is in-memory so failure never blocks start.
builder.Services.AddHttpClient<Identity.Infrastructure.Keycloak.KeycloakDirectoryAdapter>();
builder.Services.AddSingleton<IUserDirectory>(sp =>
    sp.GetRequiredService<Identity.Infrastructure.Keycloak.KeycloakDirectoryAdapter>());
builder.Services.AddSingleton<IRoleDirectory>(sp =>
    sp.GetRequiredService<Identity.Infrastructure.Keycloak.KeycloakDirectoryAdapter>());
builder.Services.AddSingleton<IPermissionRegistry, InMemoryPermissionRegistry>();
builder.Services.AddSingleton<PermissionRegistrationService>();

builder.Services.AddDbContext<Identity.Persistence.KeyManagement.KeyMetadataDbContext>((sp, o) =>
{
    var cfg = sp.GetRequiredService<IConfiguration>();
    var cs = cfg.GetConnectionString("KeyMetadata") ?? "Data Source=identity_keys.db";
    var provider = cfg["Identity:KeyMetadata:Provider"] ?? "sqlite";
    Identity.Persistence.KeyManagement.KeyMetadataDbContext.ConfigureProvider(o, provider, cs);
});
builder.Services.AddScoped<IKeyLifecycleRepository, Identity.Persistence.KeyManagement.EfKeyLifecycleRepository>();
builder.Services.AddScoped<KeyRotationService>();
builder.Services.AddHealthChecks();

builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen(o =>
{
    o.SwaggerDoc("v1",
        new Microsoft.OpenApi.OpenApiInfo
        {
            Title = "Identity Facade", Version = "v1",
            Description = "Keycloak-centric facade — auth proxy, directory, permissions, key lifecycle"
        });
    o.AddSecurityDefinition("Bearer",
        new Microsoft.OpenApi.OpenApiSecurityScheme
        {
            Type = Microsoft.OpenApi.SecuritySchemeType.Http, Scheme = "bearer", BearerFormat = "JWT",
            Description = "Keycloak-issued JWT"
        });
});
builder.Services.AddOpenApi();

var app = builder.Build();
if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI(c => c.SwaggerEndpoint("/swagger/v1/swagger.json", "Identity Facade v1"));
}

app.MapOpenApi();
// No HTTPS endpoint exists in Development/compose (plain HTTP on 5080), so a redirect here would 307 every request.
if (!app.Environment.IsDevelopment()) app.UseHttpsRedirection();
app.UseAuthentication();
app.UseAuthorization();
app.MapHealthChecks("/health/live");
app.MapGet("/api/identity/me", (ICurrentUserContext current) =>
        current.UserId is null
            ? Results.Unauthorized()
            : Results.Ok(
                new { current.UserId, current.Username, current.Roles, current.Permissions, current.SessionId }))
    .RequireAuthorization().WithTags("Users").WithName("Me").Produces<object>(200);
app.MapAuth();
app.MapUsers();
app.MapPermissions();
app.MapAdminKeys();
app.MapGrpcService<Company.Identity.Grpc.IdentityGrpcService>();
app.MapGrpcService<Company.Identity.Grpc.KeyAdminGrpcService>();
app.MapPost("/api/identity/external/organization-token",
        (OrganizationTokenRequest request) => Results.StatusCode(StatusCodes.Status501NotImplemented))
    .WithTags("Auth").WithName("ExchangeOrganizationToken");
app.Run();

