using System.Reflection;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

namespace Company.Identity.PermissionRegistration;

/// <summary>
/// Options for the permission registration client and background registration service.
/// </summary>
public sealed class PermissionRegistrationHostedOptions
{
    /// <summary>Base URL of the Identity Facade (e.g. <c>http://localhost:5080</c>).</summary>
    public required Uri IdentityServer { get; set; }

    /// <summary>Human-readable service name used in the manifest's <c>ServiceId</c>.</summary>
    public required string ServiceName { get; set; }

    /// <summary>Optional override for the service ID. Defaults to <see cref="ServiceName"/>.</summary>
    public string ServiceId { get; set; } = string.Empty;

    /// <summary>Service version reported in the manifest. Defaults to <c>"0.0.0"</c>.</summary>
    public string ServiceVersion { get; set; } = "0.0.0";

    /// <summary>Manifest schema version. Defaults to <c>"1"</c>.</summary>
    public string ManifestVersion { get; set; } = "1";

    /// <summary>Keycloak base URL for client-credentials token acquisition.</summary>
    public string? KeycloakBaseUrl { get; set; }

    /// <summary>Keycloak realm. Defaults to <c>"company"</c>.</summary>
    public string KeycloakRealm { get; set; } = "company";

    /// <summary>Keycloak client ID for the registering service.</summary>
    public string? KeycloakClientId { get; set; }

    /// <summary>Keycloak client secret for the registering service.</summary>
    public string? KeycloakClientSecret { get; set; }

    /// <summary>Delay between registration retries. Defaults to 2 seconds.</summary>
    public TimeSpan InitialRetryDelay { get; set; } = TimeSpan.FromSeconds(2);

    /// <summary>Maximum number of retries before giving up. Defaults to 8.</summary>
    public int MaximumRetries { get; set; } = 8;

    /// <summary>
    /// Assembly to scan for <c>[RequirePermission]</c> attributes.
    /// Defaults to the entry assembly at resolution time.
    /// </summary>
    internal Assembly? RegistrationAssembly { get; set; }
}

/// <summary>
/// Background service that discovers permissions from the entry assembly (or an explicit
/// assembly) and registers them with the Identity Facade on startup with exponential
/// backoff. Catches all exceptions — registration failure never blocks application startup.
/// </summary>
internal sealed class PermissionRegistrationHostedService(
    IPermissionRegistrationClient client,
    IOptions<PermissionRegistrationHostedOptions> options,
    ILogger<PermissionRegistrationHostedService> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        var opts = options.Value;
        var assembly = opts.RegistrationAssembly ?? Assembly.GetEntryAssembly();
        if (assembly is null)
        {
            logger.LogDebug("No assembly available for permission registration — skipping");
            return;
        }

        var registrationOptions = new PermissionRegistrationOptions
        {
            IdentityServer = opts.IdentityServer,
            ServiceName = opts.ServiceName,
            ServiceId = opts.ServiceId,
            ServiceVersion = opts.ServiceVersion,
            ManifestVersion = opts.ManifestVersion,
            KeycloakBaseUrl = opts.KeycloakBaseUrl,
            KeycloakRealm = opts.KeycloakRealm,
            KeycloakClientId = opts.KeycloakClientId,
            KeycloakClientSecret = opts.KeycloakClientSecret,
            InitialRetryDelay = opts.InitialRetryDelay,
            MaximumRetries = opts.MaximumRetries,
        };

        var manifest = PermissionManifest.Create(registrationOptions, assembly);

        for (var attempt = 0; attempt <= opts.MaximumRetries && !stoppingToken.IsCancellationRequested; attempt++)
        {
            try
            {
                var response = await client.RegisterAsync(manifest, stoppingToken);
                if (response is { Accepted: true })
                {
                    logger.LogInformation(
                        "Permission manifest registered for {ServiceId} v{Version} ({PermissionCount} permissions, attempt {Attempt})",
                        manifest.ServiceId, manifest.ServiceVersion, manifest.Permissions.Count, attempt + 1);
                    return;
                }

                logger.LogWarning(
                    "Permission registration not accepted for {ServiceId} (attempt {Attempt})",
                    manifest.ServiceId, attempt + 1);
            }
            catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
            {
                return;
            }
            catch (Exception ex)
            {
                logger.LogWarning(ex,
                    "Permission registration failed for {ServiceId} (attempt {Attempt})",
                    manifest.ServiceId, attempt + 1);
            }

            if (attempt < opts.MaximumRetries && !stoppingToken.IsCancellationRequested)
            {
                var delay = opts.InitialRetryDelay * Math.Pow(2, attempt);
                try
                {
                    await Task.Delay(delay, stoppingToken);
                }
                catch (OperationCanceledException)
                {
                    return;
                }
            }
        }

        logger.LogWarning(
            "Permission registration incomplete for {ServiceId} after {MaxRetries} attempts — " +
            "the application continues without registered permissions",
            manifest.ServiceId, opts.MaximumRetries);
    }
}

/// <summary>
/// Extension methods to register the permission discovery + registration pipeline.
/// </summary>
public static class PermissionRegistrationExtensions
{
    /// <summary>
    /// Registers the permission registration background service, scanning the entry assembly
    /// for <c>[RequirePermission]</c> attributes. Registration failure is best-effort and
    /// never blocks application startup.
    /// </summary>
    public static IServiceCollection AddPermissionRegistration(
        this IServiceCollection services,
        Action<PermissionRegistrationHostedOptions> configure)
    {
        return AddPermissionRegistration(services, null, configure);
    }

    /// <summary>
    /// Registers the permission registration background service, scanning the given assembly
    /// for <c>[RequirePermission]</c> attributes. Registration failure is best-effort and
    /// never blocks application startup.
    /// </summary>
    public static IServiceCollection AddPermissionRegistration(
        this IServiceCollection services,
        Assembly? assembly,
        Action<PermissionRegistrationHostedOptions> configure)
    {
        services.Configure<PermissionRegistrationHostedOptions>(o =>
        {
            configure(o);
            if (assembly is not null) o.RegistrationAssembly = assembly;
        });

        services.AddHttpClient<PermissionRegistrationClient>();
        services.TryAddSingleton<IPermissionRegistrationClient>(
            sp => sp.GetRequiredService<PermissionRegistrationClient>());
        services.AddHostedService<PermissionRegistrationHostedService>();

        return services;
    }
}

