internal sealed class PermissionRegistrationClient(
    HttpClient http,
    PermissionRegistrationOptions options) : IPermissionRegistrationClient
{
    private static readonly JsonSerializerOptions s_jsonOptions = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase
    };

    public async Task<RegistrationResponse?> RegisterAsync(PermissionManifest manifest, CancellationToken ct)
    {
        var token = await GetAccessTokenAsync(ct);
        if (string.IsNullOrEmpty(token)) return null;

        var registerUrl = $"{options.IdentityServer.TrimEnd('/')}/api/identity/permissions/register";

        try
        {
            var req = new HttpRequestMessage(HttpMethod.Post, registerUrl)
            {
                Content = JsonContent.Create(manifest, options: s_jsonOptions)
            };
            req.Headers.Add("Authorization", $"Bearer {token}");

            var res = await http.SendAsync(req, ct);
            if (res.StatusCode == HttpStatusCode.OK || res.StatusCode == HttpStatusCode.Created)
            {
                return await res.Content.ReadFromJsonAsync<RegistrationResponse>(s_jsonOptions, ct);
            }

            // 409 Conflict means already registered with the same manifest hash — treat as success.
            if (res.StatusCode == HttpStatusCode.Conflict)
            {
                return new RegistrationResponse(
                    manifest.ServiceId, manifest.ManifestVersion, manifest.ManifestHash,
                    true, []);
            }

            return null;
        }
        catch
        {
            return null;
        }
    }

    private async Task<string> GetAccessTokenAsync(CancellationToken ct)
    {
        if (string.IsNullOrEmpty(options.KeycloakBaseUrl) ||
            string.IsNullOrEmpty(options.KeycloakClientId) ||
            string.IsNullOrEmpty(options.KeycloakClientSecret))
        {
            return string.Empty;
        }

        var tokenUrl = $"{options.KeycloakBaseUrl.TrimEnd('/')}/realms/{options.KeycloakRealm}/protocol/openid-connect/token";

        try
        {
            var form = new FormUrlEncodedContent(new Dictionary<string, string>
            {
                ["grant_type"] = "client_credentials",
                ["client_id"] = options.KeycloakClientId,
                ["client_secret"] = options.KeycloakClientSecret,
            });
            var res = await http.PostAsync(tokenUrl, form, ct);
            if (!res.IsSuccessStatusCode) return string.Empty;
            var doc = JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct));
            return doc.RootElement.TryGetProperty("access_token", out var t)
                ? t.GetString() ?? string.Empty
                : string.Empty;
        }
        catch
        {
            return string.Empty;
        }
    }
}

