1	using System.Reflection;
2	using Microsoft.Extensions.DependencyInjection;
3	using Microsoft.Extensions.Hosting;
4	using Microsoft.Extensions.Logging;
5	using Microsoft.Extensions.Options;
6	
7	namespace Company.Identity.PermissionRegistration;
8	
9	/// <summary>
10	/// Background service that discovers <c>[RequirePermission]</c> attributes from an assembly,
11	/// builds a manifest and registers it with the Identity Facade using exponential backoff.
12	/// Catches all exceptions — registration failure never blocks application startup.
13	/// </summary>
14	internal sealed class PermissionRegistrationHostedService(
15	    IPermissionRegistrationClient client,
16	    IOptions<PermissionRegistrationOptions> options,
17	    ILogger<PermissionRegistrationHostedService> logger) : BackgroundService
18	{
19	    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
20	    {
21	        var opts = options.Value;
22	        var assembly = opts.RegistrationAssembly ?? Assembly.GetEntryAssembly();
23	        if (assembly is null)
24	        {
25	            logger.LogDebug("No assembly available for permission registration — skipping");
26	            return;
27	        }
28	
29	        var manifest = PermissionManifest.Create(opts, assembly);
30	
31	        for (var attempt = 0; attempt <= opts.MaximumRetries; attempt++)
32	        {
33	            if (stoppingToken.IsCancellationRequested) return;
34	            try
35	            {
36	                var response = await client.RegisterAsync(manifest, stoppingToken);
37	                if (response is { Accepted: true })
38	                {
39	                    logger.LogInformation(
40	                        "Permission manifest registered for {ServiceId} v{Version} " +
41	                        "({PermissionCount} permissions, attempt {Attempt})",
42	                        manifest.ServiceId, manifest.ServiceVersion, manifest.Permissions.Count, attempt + 1);
43	                    return;
44	                }
45	
46	                logger.LogWarning("Permission registration not accepted for {ServiceId} (attempt {Attempt})",
47	                    manifest.ServiceId, attempt + 1);
48	            }
49	            catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
50	            {
51	                return;
52	            }
53	            catch (Exception ex)
54	            {
55	                logger.LogWarning(ex, "Permission registration failed for {ServiceId} (attempt {Attempt})",
56	                    manifest.ServiceId, attempt + 1);
57	            }
58	
59	            if (attempt < opts.MaximumRetries)
60	            {
61	                var delay = opts.InitialRetryDelay * Math.Pow(2, Math.Min(attempt, 5));
62	                try
63	                {
64	                    await Task.Delay(delay, stoppingToken);
65	                }
66	                catch (OperationCanceledException)
67	                {
68	                    return;
69	                }
70	            }
71	        }
72	
73	        logger.LogWarning(
74	            "Permission registration incomplete for {ServiceId} after {MaxRetries} attempts — " +
75	            "the application continues without registered permissions",
76	            manifest.ServiceId, opts.MaximumRetries);
77	    }
78	}
79	
80	/// <summary>
81	/// Registers the permission discovery + registration pipeline: scans for
82	/// <c>[RequirePermission]</c> attributes at startup and pushes the manifest to the
83	/// Identity Facade in the background. Failure never prevents app start.
84	/// </summary>
85	public static class PermissionRegistrationExtensions
86	{
87	    /// <summary>
88	    /// Registers the permission registration background service. Scans the entry assembly
89	    /// (or <paramref name="assembly"/> when provided) for <c>[RequirePermission]</c> attributes.
90	    /// </summary>
91	    public static IServiceCollection AddPermissionRegistration(
92	        this IServiceCollection services,
93	        Action<PermissionRegistrationOptions> configure)
94	        => services.AddPermissionRegistration(null, configure);
95	
96	    /// <inheritdoc cref="AddPermissionRegistration(IServiceCollection,Action{PermissionRegistrationOptions})"/>
97	    /// <param name="assembly">Explicit assembly to scan; defaults to the entry assembly.</param>
98	    public static IServiceCollection AddPermissionRegistration(
99	        this IServiceCollection services,
100	        Assembly? assembly,
101	        Action<PermissionRegistrationOptions> configure)
102	    {
103	        services.Configure<PermissionRegistrationOptions>(o =>
104	        {
105	            configure(o);
106	            if (assembly is not null) o.RegistrationAssembly = assembly;
107	        });
108	
109	        services.AddHttpClient<IPermissionRegistrationClient, PermissionRegistrationClient>();
110	        services.AddHostedService<PermissionRegistrationHostedService>();
111	        return services;
112	    }
113	}

